PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS learning_attempts (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL,
  started_at TEXT NOT NULL,
  answered_count INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  xp_earned INTEGER NOT NULL DEFAULT 0,
  hints_used INTEGER NOT NULL DEFAULT 0,
  completed_at TEXT,
  FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS lesson_progress (
  lesson_id TEXT PRIMARY KEY,
  best_score REAL NOT NULL DEFAULT 0,
  is_completed INTEGER NOT NULL DEFAULT 0,
  attempts_count INTEGER NOT NULL DEFAULT 0,
  stars_earned INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_learning_attempts_lesson ON learning_attempts(lesson_id, started_at);
CREATE INDEX IF NOT EXISTS idx_lesson_progress_completed ON lesson_progress(is_completed);

UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 1","intro":{"title":"The Alphabet and Noun","summary":"Tiếng Anh có 26 chữ cái. Tài liệu chia a, e, i, o, u là nguyên âm; các chữ còn lại là phụ âm. Danh từ dùng để gọi tên người, nơi chốn, động vật và đồ vật. Theo cách trình bày của tài liệu, dùng an trước danh từ số ít bắt đầu bằng nguyên âm và a trước danh từ số ít bắt đầu bằng phụ âm.","rules":["Vowels: a, e, i, o, u.","Noun: tên người, nơi chốn, động vật hoặc đồ vật.","a/an + danh từ số ít; an + vowel, a + consonant theo quy tắc trong tài liệu."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u01-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tiếng Anh có 26 chữ cái. Tài liệu chia a, e, i, o, u là nguyên âm; các chữ còn lại là phụ âm. Danh từ dùng để gọi tên người, nơi chốn, động vật và đồ vật. Theo cách trình bày của tài liệu, dùng an trước danh từ số ít bắt đầu bằng nguyên âm và a trước danh từ số ít bắt đầu bằng phụ âm.\n\nQuy tắc cần nhớ:\n• Vowels: a, e, i, o, u.\n• Noun: tên người, nơi chốn, động vật hoặc đồ vật.\n• a/an + danh từ số ít; an + vowel, a + consonant theo quy tắc trong tài liệu.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"an apple","explanation":"Ví dụ đúng: an apple","hint":"Vowels: a, e, i, o, u.","difficulty":1,"points":10,"options":[{"id":"a","text":"an apple","is_correct":true},{"id":"b","text":"a apple","is_correct":false}]},{"id":"lesson-zero-u01-01-q2","type":"true_false","phase":"language_focus","question":"Theo tài liệu, a, e, i, o, u là nguyên âm.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 1.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u01-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền a hoặc an: ___ umbrella","correct_answer":"an","explanation":"Đáp án: an","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u01-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: một giáo viên","correct_answer":"a teacher","explanation":"Một cách viết theo bài học: a teacher","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u01-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 1","intro":{"title":"The Alphabet and Noun","summary":"Tiếng Anh có 26 chữ cái. Tài liệu chia a, e, i, o, u là nguyên âm; các chữ còn lại là phụ âm. Danh từ dùng để gọi tên người, nơi chốn, động vật và đồ vật. Theo cách trình bày của tài liệu, dùng an trước danh từ số ít bắt đầu bằng nguyên âm và a trước danh từ số ít bắt đầu bằng phụ âm.","rules":["Vowels: a, e, i, o, u.","Noun: tên người, nơi chốn, động vật hoặc đồ vật.","a/an + danh từ số ít; an + vowel, a + consonant theo quy tắc trong tài liệu."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u01-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn cụm đúng.","correct_answer":"a bus","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 1.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"a bus","is_correct":true},{"id":"b","text":"an bus","is_correct":false},{"id":"c","text":"a orange","is_correct":false}]},{"id":"lesson-zero-u01-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền a hoặc an: ___ umbrella","correct_answer":"an","explanation":"Đáp án: an","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u01-02-q3","type":"true_false","phase":"language_focus","question":"Theo tài liệu, a, e, i, o, u là nguyên âm.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u01-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: một giáo viên","correct_answer":"a teacher","explanation":"Đáp án mẫu: a teacher","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u01-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm The Alphabet and Noun.","correct_answer":"an apple","explanation":"Câu đúng: an apple","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"an apple","is_correct":true},{"id":"b","text":"a apple","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u01-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 1","intro":{"title":"The Alphabet and Noun","summary":"Tiếng Anh có 26 chữ cái. Tài liệu chia a, e, i, o, u là nguyên âm; các chữ còn lại là phụ âm. Danh từ dùng để gọi tên người, nơi chốn, động vật và đồ vật. Theo cách trình bày của tài liệu, dùng an trước danh từ số ít bắt đầu bằng nguyên âm và a trước danh từ số ít bắt đầu bằng phụ âm.","rules":["Vowels: a, e, i, o, u.","Noun: tên người, nơi chốn, động vật hoặc đồ vật.","a/an + danh từ số ít; an + vowel, a + consonant theo quy tắc trong tài liệu."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u01-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: một quả cam","correct_answer":"an orange","explanation":"Đáp án mẫu: an orange","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u01-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền a hoặc an: ___ camera","correct_answer":"a","explanation":"Đáp án: a","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u01-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Từ nào dưới đây là danh từ chỉ nơi chốn?","correct_answer":"school","explanation":"Đáp án: school","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"school","is_correct":true},{"id":"b","text":"teacher","is_correct":false},{"id":"c","text":"monkey","is_correct":false}]},{"id":"lesson-zero-u01-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về The Alphabet and Noun.","correct_answer":"an apple","explanation":"Ví dụ đúng: an apple","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"an apple","is_correct":true},{"id":"b","text":"a apple","is_correct":false}]},{"id":"lesson-zero-u01-03-q5","type":"true_false","phase":"language_focus","question":"Theo tài liệu, a, e, i, o, u là nguyên âm.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 1.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u01-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 2","intro":{"title":"Plural Nouns","summary":"Để chuyển danh từ số ít sang số nhiều, tài liệu dùng các quy tắc chính: thường thêm -s; một số từ thêm -es; phụ âm + y đổi thành -ies; f/fe thường đổi thành -ves; ngoài ra có các danh từ bất quy tắc cần ghi nhớ.","rules":["Phần lớn danh từ thêm -s.","Từ tận cùng o, ch, x, sh, z, s, ss thường thêm -es; tài liệu nêu một số ngoại lệ chỉ thêm -s.","Phụ âm + y: y → ies; nguyên âm + y: chỉ thêm -s.","f/fe thường → ves; có ngoại lệ.","Một số số nhiều bất quy tắc phải học thuộc."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u02-01-q1","type":"multiple_choice","phase":"pre_task","question":"Để chuyển danh từ số ít sang số nhiều, tài liệu dùng các quy tắc chính: thường thêm -s; một số từ thêm -es; phụ âm + y đổi thành -ies; f/fe thường đổi thành -ves; ngoài ra có các danh từ bất quy tắc cần ghi nhớ.\n\nQuy tắc cần nhớ:\n• Phần lớn danh từ thêm -s.\n• Từ tận cùng o, ch, x, sh, z, s, ss thường thêm -es; tài liệu nêu một số ngoại lệ chỉ thêm -s.\n• Phụ âm + y: y → ies; nguyên âm + y: chỉ thêm -s.\n• f/fe thường → ves; có ngoại lệ.\n• Một số số nhiều bất quy tắc phải học thuộc.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"baby → babies","explanation":"Ví dụ đúng: baby → babies","hint":"Phần lớn danh từ thêm -s.","difficulty":1,"points":10,"options":[{"id":"a","text":"baby → babies","is_correct":true},{"id":"b","text":"baby → babys","is_correct":false}]},{"id":"lesson-zero-u02-01-q2","type":"true_false","phase":"language_focus","question":"Theo tài liệu, toy có dạng số nhiều là toys.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 2.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u02-01-q3","type":"fill_blank","phase":"task_cycle","question":"Viết số nhiều của box: ___","correct_answer":"boxes","explanation":"Đáp án: boxes","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u02-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: hai người đàn ông","correct_answer":"two men","explanation":"Một cách viết theo bài học: two men","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u02-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 2","intro":{"title":"Plural Nouns","summary":"Để chuyển danh từ số ít sang số nhiều, tài liệu dùng các quy tắc chính: thường thêm -s; một số từ thêm -es; phụ âm + y đổi thành -ies; f/fe thường đổi thành -ves; ngoài ra có các danh từ bất quy tắc cần ghi nhớ.","rules":["Phần lớn danh từ thêm -s.","Từ tận cùng o, ch, x, sh, z, s, ss thường thêm -es; tài liệu nêu một số ngoại lệ chỉ thêm -s.","Phụ âm + y: y → ies; nguyên âm + y: chỉ thêm -s.","f/fe thường → ves; có ngoại lệ.","Một số số nhiều bất quy tắc phải học thuộc."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u02-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn dạng số nhiều đúng của leaf.","correct_answer":"leaves","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 2.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"leaves","is_correct":true},{"id":"b","text":"leafs","is_correct":false},{"id":"c","text":"leafes","is_correct":false}]},{"id":"lesson-zero-u02-02-q2","type":"fill_blank","phase":"task_cycle","question":"Viết số nhiều của box: ___","correct_answer":"boxes","explanation":"Đáp án: boxes","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u02-02-q3","type":"true_false","phase":"language_focus","question":"Theo tài liệu, toy có dạng số nhiều là toys.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u02-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: hai người đàn ông","correct_answer":"two men","explanation":"Đáp án mẫu: two men","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u02-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Plural Nouns.","correct_answer":"baby → babies","explanation":"Câu đúng: baby → babies","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"baby → babies","is_correct":true},{"id":"b","text":"baby → babys","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u02-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 2","intro":{"title":"Plural Nouns","summary":"Để chuyển danh từ số ít sang số nhiều, tài liệu dùng các quy tắc chính: thường thêm -s; một số từ thêm -es; phụ âm + y đổi thành -ies; f/fe thường đổi thành -ves; ngoài ra có các danh từ bất quy tắc cần ghi nhớ.","rules":["Phần lớn danh từ thêm -s.","Từ tận cùng o, ch, x, sh, z, s, ss thường thêm -es; tài liệu nêu một số ngoại lệ chỉ thêm -s.","Phụ âm + y: y → ies; nguyên âm + y: chỉ thêm -s.","f/fe thường → ves; có ngoại lệ.","Một số số nhiều bất quy tắc phải học thuộc."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u02-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: ba chiếc hộp","correct_answer":"three boxes","explanation":"Đáp án mẫu: three boxes","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u02-03-q2","type":"fill_blank","phase":"task_cycle","question":"Viết số nhiều của bus: ___","correct_answer":"buses","explanation":"Đáp án: buses","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u02-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn dạng số nhiều đúng của child.","correct_answer":"children","explanation":"Đáp án: children","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"children","is_correct":true},{"id":"b","text":"childs","is_correct":false},{"id":"c","text":"childes","is_correct":false}]},{"id":"lesson-zero-u02-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Plural Nouns.","correct_answer":"baby → babies","explanation":"Ví dụ đúng: baby → babies","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"baby → babies","is_correct":true},{"id":"b","text":"baby → babys","is_correct":false}]},{"id":"lesson-zero-u02-03-q5","type":"true_false","phase":"language_focus","question":"Theo tài liệu, toy có dạng số nhiều là toys.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 2.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u02-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 3","intro":{"title":"Personal Pronouns","summary":"Đại từ nhân xưng làm chủ ngữ gồm I, you, we, they, he, she, it. Tài liệu giải nghĩa lần lượt là tôi; bạn/các bạn; chúng tôi/chúng ta; họ/chúng nó; anh ấy; cô ấy; nó.","rules":["I = tôi.","you = bạn/các bạn.","we = chúng tôi/chúng ta; they = họ/chúng nó.","he = anh ấy; she = cô ấy; it = nó."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u03-01-q1","type":"multiple_choice","phase":"pre_task","question":"Đại từ nhân xưng làm chủ ngữ gồm I, you, we, they, he, she, it. Tài liệu giải nghĩa lần lượt là tôi; bạn/các bạn; chúng tôi/chúng ta; họ/chúng nó; anh ấy; cô ấy; nó.\n\nQuy tắc cần nhớ:\n• I = tôi.\n• you = bạn/các bạn.\n• we = chúng tôi/chúng ta; they = họ/chúng nó.\n• he = anh ấy; she = cô ấy; it = nó.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"She is a teacher.","explanation":"Ví dụ đúng: She is a teacher.","hint":"I = tôi.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a teacher.","is_correct":true},{"id":"b","text":"Her is a teacher.","is_correct":false}]},{"id":"lesson-zero-u03-01-q2","type":"true_false","phase":"language_focus","question":"He được dùng cho ''anh ấy''.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 3.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u03-01-q3","type":"fill_blank","phase":"task_cycle","question":"Thay ''Mary'' bằng đại từ chủ ngữ: ___ is a student.","correct_answer":"She","explanation":"Đáp án: She","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u03-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ là học sinh.","correct_answer":"They are students.","explanation":"Một cách viết theo bài học: They are students.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u03-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 3","intro":{"title":"Personal Pronouns","summary":"Đại từ nhân xưng làm chủ ngữ gồm I, you, we, they, he, she, it. Tài liệu giải nghĩa lần lượt là tôi; bạn/các bạn; chúng tôi/chúng ta; họ/chúng nó; anh ấy; cô ấy; nó.","rules":["I = tôi.","you = bạn/các bạn.","we = chúng tôi/chúng ta; they = họ/chúng nó.","he = anh ấy; she = cô ấy; it = nó."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u03-02-q1","type":"multiple_choice","phase":"pre_task","question":"Đại từ nào có nghĩa ''chúng tôi/chúng ta''?","correct_answer":"we","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 3.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"we","is_correct":true},{"id":"b","text":"they","is_correct":false},{"id":"c","text":"it","is_correct":false}]},{"id":"lesson-zero-u03-02-q2","type":"fill_blank","phase":"task_cycle","question":"Thay ''Mary'' bằng đại từ chủ ngữ: ___ is a student.","correct_answer":"She","explanation":"Đáp án: She","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u03-02-q3","type":"true_false","phase":"language_focus","question":"He được dùng cho ''anh ấy''.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u03-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ là học sinh.","correct_answer":"They are students.","explanation":"Đáp án mẫu: They are students.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u03-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Personal Pronouns.","correct_answer":"She is a teacher.","explanation":"Câu đúng: She is a teacher.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a teacher.","is_correct":true},{"id":"b","text":"Her is a teacher.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u03-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 3","intro":{"title":"Personal Pronouns","summary":"Đại từ nhân xưng làm chủ ngữ gồm I, you, we, they, he, she, it. Tài liệu giải nghĩa lần lượt là tôi; bạn/các bạn; chúng tôi/chúng ta; họ/chúng nó; anh ấy; cô ấy; nó.","rules":["I = tôi.","you = bạn/các bạn.","we = chúng tôi/chúng ta; they = họ/chúng nó.","he = anh ấy; she = cô ấy; it = nó."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u03-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Cô ấy là bạn của tôi.","correct_answer":"She is my friend.","explanation":"Đáp án mẫu: She is my friend.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u03-03-q2","type":"fill_blank","phase":"task_cycle","question":"Thay ''Tom'' bằng đại từ: ___ is twelve.","correct_answer":"He","explanation":"Đáp án: He","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u03-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Đại từ phù hợp với ''a book'' là gì?","correct_answer":"it","explanation":"Đáp án: it","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"it","is_correct":true},{"id":"b","text":"he","is_correct":false},{"id":"c","text":"they","is_correct":false}]},{"id":"lesson-zero-u03-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Personal Pronouns.","correct_answer":"She is a teacher.","explanation":"Ví dụ đúng: She is a teacher.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a teacher.","is_correct":true},{"id":"b","text":"Her is a teacher.","is_correct":false}]},{"id":"lesson-zero-u03-03-q5","type":"true_false","phase":"language_focus","question":"He được dùng cho ''anh ấy''.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 3.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u03-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 4","intro":{"title":"Verb To Be","summary":"Động từ to be ở hiện tại dùng am, is, are. I đi với am; he/she/it và chủ ngữ số ít đi với is; you/we/they và chủ ngữ số nhiều đi với are. Phủ định thêm not; câu hỏi đưa am/is/are lên trước chủ ngữ.","rules":["I am.","He/She/It + is.","You/We/They + are.","Phủ định: am not / isn''t / aren''t.","Câu hỏi: Am/Is/Are + subject ...?"]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u04-01-q1","type":"multiple_choice","phase":"pre_task","question":"Động từ to be ở hiện tại dùng am, is, are. I đi với am; he/she/it và chủ ngữ số ít đi với is; you/we/they và chủ ngữ số nhiều đi với are. Phủ định thêm not; câu hỏi đưa am/is/are lên trước chủ ngữ.\n\nQuy tắc cần nhớ:\n• I am.\n• He/She/It + is.\n• You/We/They + are.\n• Phủ định: am not / isn''t / aren''t.\n• Câu hỏi: Am/Is/Are + subject ...?\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"She is a nurse.","explanation":"Ví dụ đúng: She is a nurse.","hint":"I am.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a nurse.","is_correct":true},{"id":"b","text":"She are a nurse.","is_correct":false}]},{"id":"lesson-zero-u04-01-q2","type":"true_false","phase":"language_focus","question":"You đi với are.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 4.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u04-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền am/is/are: I ___ a student.","correct_answer":"am","explanation":"Đáp án: am","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u04-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ không phải là bác sĩ.","correct_answer":"They are not doctors.","explanation":"Một cách viết theo bài học: They are not doctors.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u04-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 4","intro":{"title":"Verb To Be","summary":"Động từ to be ở hiện tại dùng am, is, are. I đi với am; he/she/it và chủ ngữ số ít đi với is; you/we/they và chủ ngữ số nhiều đi với are. Phủ định thêm not; câu hỏi đưa am/is/are lên trước chủ ngữ.","rules":["I am.","He/She/It + is.","You/We/They + are.","Phủ định: am not / isn''t / aren''t.","Câu hỏi: Am/Is/Are + subject ...?"]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u04-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"He is a cook.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 4.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"He is a cook.","is_correct":true},{"id":"b","text":"He are a cook.","is_correct":false},{"id":"c","text":"He am a cook.","is_correct":false}]},{"id":"lesson-zero-u04-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền am/is/are: I ___ a student.","correct_answer":"am","explanation":"Đáp án: am","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u04-02-q3","type":"true_false","phase":"language_focus","question":"You đi với are.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u04-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ không phải là bác sĩ.","correct_answer":"They are not doctors.","explanation":"Đáp án mẫu: They are not doctors.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u04-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Verb To Be.","correct_answer":"She is a nurse.","explanation":"Câu đúng: She is a nurse.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a nurse.","is_correct":true},{"id":"b","text":"She are a nurse.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u04-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 4","intro":{"title":"Verb To Be","summary":"Động từ to be ở hiện tại dùng am, is, are. I đi với am; he/she/it và chủ ngữ số ít đi với is; you/we/they và chủ ngữ số nhiều đi với are. Phủ định thêm not; câu hỏi đưa am/is/are lên trước chủ ngữ.","rules":["I am.","He/She/It + is.","You/We/They + are.","Phủ định: am not / isn''t / aren''t.","Câu hỏi: Am/Is/Are + subject ...?"]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u04-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Bạn có phải là học sinh không?","correct_answer":"Are you a student?","explanation":"Đáp án mẫu: Are you a student?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u04-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: We ___ firefighters.","correct_answer":"are","explanation":"Đáp án: are","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u04-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Phủ định đúng của ''She is a teacher.'' là:","correct_answer":"She isn''t a teacher.","explanation":"Đáp án: She isn''t a teacher.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"She isn''t a teacher.","is_correct":true},{"id":"b","text":"She don''t a teacher.","is_correct":false},{"id":"c","text":"She aren''t a teacher.","is_correct":false}]},{"id":"lesson-zero-u04-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Verb To Be.","correct_answer":"She is a nurse.","explanation":"Ví dụ đúng: She is a nurse.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a nurse.","is_correct":true},{"id":"b","text":"She are a nurse.","is_correct":false}]},{"id":"lesson-zero-u04-03-q5","type":"true_false","phase":"language_focus","question":"You đi với are.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 4.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u04-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 5","intro":{"title":"This / That / These / Those","summary":"This/these dùng cho người hoặc vật ở gần; that/those dùng cho người hoặc vật ở xa. This/that là số ít; these/those là số nhiều.","rules":["This is: một người/vật ở gần.","These are: từ hai người/vật trở lên ở gần.","That is: một người/vật ở xa.","Those are: từ hai người/vật trở lên ở xa."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u05-01-q1","type":"multiple_choice","phase":"pre_task","question":"This/these dùng cho người hoặc vật ở gần; that/those dùng cho người hoặc vật ở xa. This/that là số ít; these/those là số nhiều.\n\nQuy tắc cần nhớ:\n• This is: một người/vật ở gần.\n• These are: từ hai người/vật trở lên ở gần.\n• That is: một người/vật ở xa.\n• Those are: từ hai người/vật trở lên ở xa.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"These are books.","explanation":"Ví dụ đúng: These are books.","hint":"This is: một người/vật ở gần.","difficulty":1,"points":10,"options":[{"id":"a","text":"These are books.","is_correct":true},{"id":"b","text":"This are books.","is_correct":false}]},{"id":"lesson-zero-u05-01-q2","type":"true_false","phase":"language_focus","question":"That dùng cho một người hoặc vật ở xa.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 5.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u05-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền từ phù hợp cho số nhiều ở xa: ___ are elephants.","correct_answer":"Those","explanation":"Đáp án: Those","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u05-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đây là một quyển sách.","correct_answer":"This is a book.","explanation":"Một cách viết theo bài học: This is a book.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u05-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 5","intro":{"title":"This / That / These / Those","summary":"This/these dùng cho người hoặc vật ở gần; that/those dùng cho người hoặc vật ở xa. This/that là số ít; these/those là số nhiều.","rules":["This is: một người/vật ở gần.","These are: từ hai người/vật trở lên ở gần.","That is: một người/vật ở xa.","Those are: từ hai người/vật trở lên ở xa."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u05-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng cho nhiều chiếc bút ở gần.","correct_answer":"These are pens.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 5.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"These are pens.","is_correct":true},{"id":"b","text":"This is pens.","is_correct":false},{"id":"c","text":"Those is pens.","is_correct":false}]},{"id":"lesson-zero-u05-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền từ phù hợp cho số nhiều ở xa: ___ are elephants.","correct_answer":"Those","explanation":"Đáp án: Those","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u05-02-q3","type":"true_false","phase":"language_focus","question":"That dùng cho một người hoặc vật ở xa.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u05-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đây là một quyển sách.","correct_answer":"This is a book.","explanation":"Đáp án mẫu: This is a book.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u05-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm This / That / These / Those.","correct_answer":"These are books.","explanation":"Câu đúng: These are books.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"These are books.","is_correct":true},{"id":"b","text":"This are books.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u05-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 5","intro":{"title":"This / That / These / Those","summary":"This/these dùng cho người hoặc vật ở gần; that/those dùng cho người hoặc vật ở xa. This/that là số ít; these/those là số nhiều.","rules":["This is: một người/vật ở gần.","These are: từ hai người/vật trở lên ở gần.","That is: một người/vật ở xa.","Those are: từ hai người/vật trở lên ở xa."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u05-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Kia là một con voi.","correct_answer":"That is an elephant.","explanation":"Đáp án mẫu: That is an elephant.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u05-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: ___ is my classroom. (một nơi ở gần)","correct_answer":"This","explanation":"Đáp án: This","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u05-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Dạng số nhiều của ''That is a box.'' bắt đầu bằng từ nào?","correct_answer":"Those","explanation":"Đáp án: Those","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Those","is_correct":true},{"id":"b","text":"These","is_correct":false},{"id":"c","text":"This","is_correct":false}]},{"id":"lesson-zero-u05-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về This / That / These / Those.","correct_answer":"These are books.","explanation":"Ví dụ đúng: These are books.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"These are books.","is_correct":true},{"id":"b","text":"This are books.","is_correct":false}]},{"id":"lesson-zero-u05-03-q5","type":"true_false","phase":"language_focus","question":"That dùng cho một người hoặc vật ở xa.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 5.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u05-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home","intro":{"title":"There Is / There Are","summary":"There is dùng để nói có một người/vật; there are dùng với số nhiều. Phủ định là there isn''t/there aren''t; câu hỏi là Is there...? / Are there...?.","rules":["There is / there''s + số ít.","There are + số nhiều.","There isn''t / there aren''t để phủ định.","Is there...? / Are there...? để hỏi."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u06-01-q1","type":"multiple_choice","phase":"pre_task","question":"There is dùng để nói có một người/vật; there are dùng với số nhiều. Phủ định là there isn''t/there aren''t; câu hỏi là Is there...? / Are there...?.\n\nQuy tắc cần nhớ:\n• There is / there''s + số ít.\n• There are + số nhiều.\n• There isn''t / there aren''t để phủ định.\n• Is there...? / Are there...? để hỏi.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"There are two pens on the desk.","explanation":"Ví dụ đúng: There are two pens on the desk.","hint":"There is / there''s + số ít.","difficulty":1,"points":10,"options":[{"id":"a","text":"There are two pens on the desk.","is_correct":true},{"id":"b","text":"There is two pens on the desk.","is_correct":false}]},{"id":"lesson-zero-u06-01-q2","type":"true_false","phase":"language_focus","question":"Are there...? dùng để hỏi về số nhiều.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u06-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền is/are: There ___ a book on the desk.","correct_answer":"is","explanation":"Đáp án: is","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u06-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Có hai cửa sổ trong phòng.","correct_answer":"There are two windows in the room.","explanation":"Một cách viết theo bài học: There are two windows in the room.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u06-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home","intro":{"title":"There Is / There Are","summary":"There is dùng để nói có một người/vật; there are dùng với số nhiều. Phủ định là there isn''t/there aren''t; câu hỏi là Is there...? / Are there...?.","rules":["There is / there''s + số ít.","There are + số nhiều.","There isn''t / there aren''t để phủ định.","Is there...? / Are there...? để hỏi."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u06-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"There is a lamp.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"There is a lamp.","is_correct":true},{"id":"b","text":"There are a lamp.","is_correct":false},{"id":"c","text":"There is two lamps.","is_correct":false}]},{"id":"lesson-zero-u06-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền is/are: There ___ a book on the desk.","correct_answer":"is","explanation":"Đáp án: is","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u06-02-q3","type":"true_false","phase":"language_focus","question":"Are there...? dùng để hỏi về số nhiều.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u06-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Có hai cửa sổ trong phòng.","correct_answer":"There are two windows in the room.","explanation":"Đáp án mẫu: There are two windows in the room.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u06-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm There Is / There Are.","correct_answer":"There are two pens on the desk.","explanation":"Câu đúng: There are two pens on the desk.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"There are two pens on the desk.","is_correct":true},{"id":"b","text":"There is two pens on the desk.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u06-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home","intro":{"title":"There Is / There Are","summary":"There is dùng để nói có một người/vật; there are dùng với số nhiều. Phủ định là there isn''t/there aren''t; câu hỏi là Is there...? / Are there...?.","rules":["There is / there''s + số ít.","There are + số nhiều.","There isn''t / there aren''t để phủ định.","Is there...? / Are there...? để hỏi."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u06-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Không có chiếc ghế nào trong phòng.","correct_answer":"There aren''t any chairs in the room.","explanation":"Đáp án mẫu: There aren''t any chairs in the room.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u06-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: ___ there a mirror in the room?","correct_answer":"Is","explanation":"Đáp án: Is","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u06-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Câu hỏi đúng với ''two books'' là:","correct_answer":"Are there two books?","explanation":"Đáp án: Are there two books?","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Are there two books?","is_correct":true},{"id":"b","text":"Is there two books?","is_correct":false},{"id":"c","text":"There are two books?","is_correct":false}]},{"id":"lesson-zero-u06-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về There Is / There Are.","correct_answer":"There are two pens on the desk.","explanation":"Ví dụ đúng: There are two pens on the desk.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"There are two pens on the desk.","is_correct":true},{"id":"b","text":"There is two pens on the desk.","is_correct":false}]},{"id":"lesson-zero-u06-03-q5","type":"true_false","phase":"language_focus","question":"Are there...? dùng để hỏi về số nhiều.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 6; Bài tập Tiếng Anh 6 – Unit 2 My Home.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u06-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 7","intro":{"title":"Possessive","summary":"Tài liệu ghép đại từ nhân xưng với tính từ sở hữu và đại từ sở hữu: I-my-mine, you-your-yours, we-our-ours, they-their-theirs, he-his-his, she-her-hers, it-its. Tính từ sở hữu đứng trước danh từ; đại từ sở hữu có thể đứng độc lập.","rules":["Possessive adjective đứng trước danh từ: my book, his book.","Possessive pronoun thay cho cụm danh từ sở hữu: mine, yours, ours, theirs, his, hers.","I→my/mine; you→your/yours; we→our/ours; they→their/theirs; he→his; she→her/hers; it→its."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u07-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu ghép đại từ nhân xưng với tính từ sở hữu và đại từ sở hữu: I-my-mine, you-your-yours, we-our-ours, they-their-theirs, he-his-his, she-her-hers, it-its. Tính từ sở hữu đứng trước danh từ; đại từ sở hữu có thể đứng độc lập.\n\nQuy tắc cần nhớ:\n• Possessive adjective đứng trước danh từ: my book, his book.\n• Possessive pronoun thay cho cụm danh từ sở hữu: mine, yours, ours, theirs, his, hers.\n• I→my/mine; you→your/yours; we→our/ours; they→their/theirs; he→his; she→her/hers; it→its.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"This is my book.","explanation":"Ví dụ đúng: This is my book.","hint":"Possessive adjective đứng trước danh từ: my book, his book.","difficulty":1,"points":10,"options":[{"id":"a","text":"This is my book.","is_correct":true},{"id":"b","text":"This is mine book.","is_correct":false}]},{"id":"lesson-zero-u07-01-q2","type":"true_false","phase":"language_focus","question":"Tính từ sở hữu đứng trước danh từ.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 7.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u07-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền tính từ sở hữu: She has a bag. ___ bag is new.","correct_answer":"Her","explanation":"Đáp án: Her","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u07-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đó là xe của họ.","correct_answer":"That is their car.","explanation":"Một cách viết theo bài học: That is their car.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u07-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 7","intro":{"title":"Possessive","summary":"Tài liệu ghép đại từ nhân xưng với tính từ sở hữu và đại từ sở hữu: I-my-mine, you-your-yours, we-our-ours, they-their-theirs, he-his-his, she-her-hers, it-its. Tính từ sở hữu đứng trước danh từ; đại từ sở hữu có thể đứng độc lập.","rules":["Possessive adjective đứng trước danh từ: my book, his book.","Possessive pronoun thay cho cụm danh từ sở hữu: mine, yours, ours, theirs, his, hers.","I→my/mine; you→your/yours; we→our/ours; they→their/theirs; he→his; she→her/hers; it→its."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u07-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn tính từ sở hữu của ''we''.","correct_answer":"our","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 7.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"our","is_correct":true},{"id":"b","text":"ours","is_correct":false},{"id":"c","text":"us","is_correct":false}]},{"id":"lesson-zero-u07-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền tính từ sở hữu: She has a bag. ___ bag is new.","correct_answer":"Her","explanation":"Đáp án: Her","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u07-02-q3","type":"true_false","phase":"language_focus","question":"Tính từ sở hữu đứng trước danh từ.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u07-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đó là xe của họ.","correct_answer":"That is their car.","explanation":"Đáp án mẫu: That is their car.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u07-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Possessive.","correct_answer":"This is my book.","explanation":"Câu đúng: This is my book.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"This is my book.","is_correct":true},{"id":"b","text":"This is mine book.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u07-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 7","intro":{"title":"Possessive","summary":"Tài liệu ghép đại từ nhân xưng với tính từ sở hữu và đại từ sở hữu: I-my-mine, you-your-yours, we-our-ours, they-their-theirs, he-his-his, she-her-hers, it-its. Tính từ sở hữu đứng trước danh từ; đại từ sở hữu có thể đứng độc lập.","rules":["Possessive adjective đứng trước danh từ: my book, his book.","Possessive pronoun thay cho cụm danh từ sở hữu: mine, yours, ours, theirs, his, hers.","I→my/mine; you→your/yours; we→our/ours; they→their/theirs; he→his; she→her/hers; it→its."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u07-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Quyển sách này là của tôi.","correct_answer":"This book is mine.","explanation":"Đáp án mẫu: This book is mine.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u07-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: They have a house. ___ house is big.","correct_answer":"Their","explanation":"Đáp án: Their","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u07-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn đại từ sở hữu tương ứng với ''she''.","correct_answer":"hers","explanation":"Đáp án: hers","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"hers","is_correct":true},{"id":"b","text":"her","is_correct":false},{"id":"c","text":"she","is_correct":false}]},{"id":"lesson-zero-u07-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Possessive.","correct_answer":"This is my book.","explanation":"Ví dụ đúng: This is my book.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"This is my book.","is_correct":true},{"id":"b","text":"This is mine book.","is_correct":false}]},{"id":"lesson-zero-u07-03-q5","type":"true_false","phase":"language_focus","question":"Tính từ sở hữu đứng trước danh từ.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 7.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u07-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6","intro":{"title":"Prepositions of Time","summary":"Tài liệu dùng in với buổi/tháng/mùa/năm; on với ngày và ngày tháng; at với giờ cụ thể và một số mốc như night, noon, midnight. Ngoài ra còn có for, since, until/till, before, after, during, by, from...to.","rules":["in the morning/afternoon/evening; in January; in 2020.","on Monday; on April 21st; on my birthday.","at 5 o''clock; at night; at noon; at midnight.","for + khoảng thời gian; since + mốc thời gian."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u08-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu dùng in với buổi/tháng/mùa/năm; on với ngày và ngày tháng; at với giờ cụ thể và một số mốc như night, noon, midnight. Ngoài ra còn có for, since, until/till, before, after, during, by, from...to.\n\nQuy tắc cần nhớ:\n• in the morning/afternoon/evening; in January; in 2020.\n• on Monday; on April 21st; on my birthday.\n• at 5 o''clock; at night; at noon; at midnight.\n• for + khoảng thời gian; since + mốc thời gian.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"at 6 o''clock","explanation":"Ví dụ đúng: at 6 o''clock","hint":"in the morning/afternoon/evening; in January; in 2020.","difficulty":1,"points":10,"options":[{"id":"a","text":"at 6 o''clock","is_correct":true},{"id":"b","text":"in 6 o''clock","is_correct":false}]},{"id":"lesson-zero-u08-01-q2","type":"true_false","phase":"language_focus","question":"Theo tài liệu, at night là đúng.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u08-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền in/on/at: ___ Monday","correct_answer":"on","explanation":"Đáp án: on","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u08-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: vào tháng Chín","correct_answer":"in September","explanation":"Một cách viết theo bài học: in September","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u08-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6","intro":{"title":"Prepositions of Time","summary":"Tài liệu dùng in với buổi/tháng/mùa/năm; on với ngày và ngày tháng; at với giờ cụ thể và một số mốc như night, noon, midnight. Ngoài ra còn có for, since, until/till, before, after, during, by, from...to.","rules":["in the morning/afternoon/evening; in January; in 2020.","on Monday; on April 21st; on my birthday.","at 5 o''clock; at night; at noon; at midnight.","for + khoảng thời gian; since + mốc thời gian."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u08-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn giới từ đúng: ___ 2007","correct_answer":"in","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"in","is_correct":true},{"id":"b","text":"on","is_correct":false},{"id":"c","text":"at","is_correct":false}]},{"id":"lesson-zero-u08-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền in/on/at: ___ Monday","correct_answer":"on","explanation":"Đáp án: on","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u08-02-q3","type":"true_false","phase":"language_focus","question":"Theo tài liệu, at night là đúng.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u08-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: vào tháng Chín","correct_answer":"in September","explanation":"Đáp án mẫu: in September","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u08-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Prepositions of Time.","correct_answer":"at 6 o''clock","explanation":"Câu đúng: at 6 o''clock","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"at 6 o''clock","is_correct":true},{"id":"b","text":"in 6 o''clock","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u08-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6","intro":{"title":"Prepositions of Time","summary":"Tài liệu dùng in với buổi/tháng/mùa/năm; on với ngày và ngày tháng; at với giờ cụ thể và một số mốc như night, noon, midnight. Ngoài ra còn có for, since, until/till, before, after, during, by, from...to.","rules":["in the morning/afternoon/evening; in January; in 2020.","on Monday; on April 21st; on my birthday.","at 5 o''clock; at night; at noon; at midnight.","for + khoảng thời gian; since + mốc thời gian."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u08-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: vào lúc 5 giờ 30","correct_answer":"at 5:30","explanation":"Đáp án mẫu: at 5:30","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u08-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền in/on/at: ___ March 2nd","correct_answer":"on","explanation":"Đáp án: on","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u08-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn cụm đúng.","correct_answer":"in the morning","explanation":"Đáp án: in the morning","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"in the morning","is_correct":true},{"id":"b","text":"at the morning","is_correct":false},{"id":"c","text":"on the morning","is_correct":false}]},{"id":"lesson-zero-u08-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Prepositions of Time.","correct_answer":"at 6 o''clock","explanation":"Ví dụ đúng: at 6 o''clock","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"at 6 o''clock","is_correct":true},{"id":"b","text":"in 6 o''clock","is_correct":false}]},{"id":"lesson-zero-u08-03-q5","type":"true_false","phase":"language_focus","question":"Theo tài liệu, at night là đúng.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 8; Bài tập Tiếng Anh 6 – Unit 6.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u08-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4","intro":{"title":"Prepositions of Place","summary":"Tài liệu dùng at cho một điểm/địa điểm nhỏ, on cho bề mặt và một số phương tiện, in cho không gian được bao quanh hoặc địa điểm lớn. Các giới từ vị trí khác gồm under, above/over, behind, in front of, between, among, next to, near, opposite.","rules":["at home / at school / at the bus stop.","on the table / on the wall / on a bus; nhưng in a car.","in a box / in a room / in London / in Vietnam.","under, above, behind, in front of, between, among, next to, near, opposite."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u09-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu dùng at cho một điểm/địa điểm nhỏ, on cho bề mặt và một số phương tiện, in cho không gian được bao quanh hoặc địa điểm lớn. Các giới từ vị trí khác gồm under, above/over, behind, in front of, between, among, next to, near, opposite.\n\nQuy tắc cần nhớ:\n• at home / at school / at the bus stop.\n• on the table / on the wall / on a bus; nhưng in a car.\n• in a box / in a room / in London / in Vietnam.\n• under, above, behind, in front of, between, among, next to, near, opposite.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"The book is on the table.","explanation":"Ví dụ đúng: The book is on the table.","hint":"at home / at school / at the bus stop.","difficulty":1,"points":10,"options":[{"id":"a","text":"The book is on the table.","is_correct":true},{"id":"b","text":"The book is at the table surface.","is_correct":false}]},{"id":"lesson-zero-u09-01-q2","type":"true_false","phase":"language_focus","question":"Tài liệu ghi ''in a car'' nhưng ''on a bus''.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u09-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền: The cat is ___ the table. (ở dưới)","correct_answer":"under","explanation":"Đáp án: under","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u09-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Trường của tôi ở gần nhà.","correct_answer":"My school is near my house.","explanation":"Một cách viết theo bài học: My school is near my house.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u09-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4","intro":{"title":"Prepositions of Place","summary":"Tài liệu dùng at cho một điểm/địa điểm nhỏ, on cho bề mặt và một số phương tiện, in cho không gian được bao quanh hoặc địa điểm lớn. Các giới từ vị trí khác gồm under, above/over, behind, in front of, between, among, next to, near, opposite.","rules":["at home / at school / at the bus stop.","on the table / on the wall / on a bus; nhưng in a car.","in a box / in a room / in London / in Vietnam.","under, above, behind, in front of, between, among, next to, near, opposite."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u09-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn giới từ: I am ___ home.","correct_answer":"at","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"at","is_correct":true},{"id":"b","text":"in","is_correct":false},{"id":"c","text":"on","is_correct":false}]},{"id":"lesson-zero-u09-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: The cat is ___ the table. (ở dưới)","correct_answer":"under","explanation":"Đáp án: under","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u09-02-q3","type":"true_false","phase":"language_focus","question":"Tài liệu ghi ''in a car'' nhưng ''on a bus''.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u09-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Trường của tôi ở gần nhà.","correct_answer":"My school is near my house.","explanation":"Đáp án mẫu: My school is near my house.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u09-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Prepositions of Place.","correct_answer":"The book is on the table.","explanation":"Câu đúng: The book is on the table.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"The book is on the table.","is_correct":true},{"id":"b","text":"The book is at the table surface.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u09-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4","intro":{"title":"Prepositions of Place","summary":"Tài liệu dùng at cho một điểm/địa điểm nhỏ, on cho bề mặt và một số phương tiện, in cho không gian được bao quanh hoặc địa điểm lớn. Các giới từ vị trí khác gồm under, above/over, behind, in front of, between, among, next to, near, opposite.","rules":["at home / at school / at the bus stop.","on the table / on the wall / on a bus; nhưng in a car.","in a box / in a room / in London / in Vietnam.","under, above, behind, in front of, between, among, next to, near, opposite."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u09-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Nhà tôi ở đối diện bưu điện.","correct_answer":"My house is opposite a post office.","explanation":"Đáp án mẫu: My house is opposite a post office.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u09-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: I sit ___ my mum and my dad.","correct_answer":"between","explanation":"Đáp án: between","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u09-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn cụm đúng cho ''trên tường''.","correct_answer":"on the wall","explanation":"Đáp án: on the wall","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"on the wall","is_correct":true},{"id":"b","text":"in the wall","is_correct":false},{"id":"c","text":"at the wall","is_correct":false}]},{"id":"lesson-zero-u09-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Prepositions of Place.","correct_answer":"The book is on the table.","explanation":"Ví dụ đúng: The book is on the table.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"The book is on the table.","is_correct":true},{"id":"b","text":"The book is at the table surface.","is_correct":false}]},{"id":"lesson-zero-u09-03-q5","type":"true_false","phase":"language_focus","question":"Tài liệu ghi ''in a car'' nhưng ''on a bus''.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 9; Bài tập Tiếng Anh 6 – Unit 2 & 4.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u09-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6","intro":{"title":"Can and Basic Modals","summary":"Unit 10 của tài liệu ngữ pháp tập trung vào can/can''t: can + động từ nguyên thể, cannot/can''t để phủ định, Can + chủ ngữ...? để hỏi khả năng. Bài tập Tiếng Anh 6 mở rộng với must/mustn''t và should/shouldn''t.","rules":["I/you/he/she/we/they/it + can + V.","Phủ định: cannot = can''t.","Câu hỏi: Can + subject + V...?","Mở rộng từ bài tập: must/mustn''t cho yêu cầu/cấm; should/shouldn''t cho lời khuyên."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u10-01-q1","type":"multiple_choice","phase":"pre_task","question":"Unit 10 của tài liệu ngữ pháp tập trung vào can/can''t: can + động từ nguyên thể, cannot/can''t để phủ định, Can + chủ ngữ...? để hỏi khả năng. Bài tập Tiếng Anh 6 mở rộng với must/mustn''t và should/shouldn''t.\n\nQuy tắc cần nhớ:\n• I/you/he/she/we/they/it + can + V.\n• Phủ định: cannot = can''t.\n• Câu hỏi: Can + subject + V...?\n• Mở rộng từ bài tập: must/mustn''t cho yêu cầu/cấm; should/shouldn''t cho lời khuyên.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"I can swim.","explanation":"Ví dụ đúng: I can swim.","hint":"I/you/he/she/we/they/it + can + V.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can swim.","is_correct":true},{"id":"b","text":"I can to swim.","is_correct":false}]},{"id":"lesson-zero-u10-01-q2","type":"true_false","phase":"language_focus","question":"Sau can, tài liệu dùng động từ nguyên thể.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u10-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền can/can''t: Birds ___ fly.","correct_answer":"can","explanation":"Đáp án: can","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u10-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Anh ấy không thể đi xe đạp.","correct_answer":"He can''t ride a bicycle.","explanation":"Một cách viết theo bài học: He can''t ride a bicycle.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u10-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6","intro":{"title":"Can and Basic Modals","summary":"Unit 10 của tài liệu ngữ pháp tập trung vào can/can''t: can + động từ nguyên thể, cannot/can''t để phủ định, Can + chủ ngữ...? để hỏi khả năng. Bài tập Tiếng Anh 6 mở rộng với must/mustn''t và should/shouldn''t.","rules":["I/you/he/she/we/they/it + can + V.","Phủ định: cannot = can''t.","Câu hỏi: Can + subject + V...?","Mở rộng từ bài tập: must/mustn''t cho yêu cầu/cấm; should/shouldn''t cho lời khuyên."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u10-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu hỏi đúng.","correct_answer":"Can you swim?","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"Can you swim?","is_correct":true},{"id":"b","text":"Do you can swim?","is_correct":false},{"id":"c","text":"Can you to swim?","is_correct":false}]},{"id":"lesson-zero-u10-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền can/can''t: Birds ___ fly.","correct_answer":"can","explanation":"Đáp án: can","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u10-02-q3","type":"true_false","phase":"language_focus","question":"Sau can, tài liệu dùng động từ nguyên thể.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u10-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Anh ấy không thể đi xe đạp.","correct_answer":"He can''t ride a bicycle.","explanation":"Đáp án mẫu: He can''t ride a bicycle.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u10-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Can and Basic Modals.","correct_answer":"I can swim.","explanation":"Câu đúng: I can swim.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can swim.","is_correct":true},{"id":"b","text":"I can to swim.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u10-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6","intro":{"title":"Can and Basic Modals","summary":"Unit 10 của tài liệu ngữ pháp tập trung vào can/can''t: can + động từ nguyên thể, cannot/can''t để phủ định, Can + chủ ngữ...? để hỏi khả năng. Bài tập Tiếng Anh 6 mở rộng với must/mustn''t và should/shouldn''t.","rules":["I/you/he/she/we/they/it + can + V.","Phủ định: cannot = can''t.","Câu hỏi: Can + subject + V...?","Mở rộng từ bài tập: must/mustn''t cho yêu cầu/cấm; should/shouldn''t cho lời khuyên."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u10-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Bạn nên học chăm chỉ.","correct_answer":"You should study hard.","explanation":"Đáp án mẫu: You should study hard.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u10-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền modal phù hợp: You ___ use your phone in the exam. (bị cấm)","correct_answer":"mustn''t","explanation":"Đáp án: mustn''t","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u10-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Câu nào là lời khuyên?","correct_answer":"You should exercise.","explanation":"Đáp án: You should exercise.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"You should exercise.","is_correct":true},{"id":"b","text":"You can swim.","is_correct":false},{"id":"c","text":"You mustn''t park here.","is_correct":false}]},{"id":"lesson-zero-u10-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Can and Basic Modals.","correct_answer":"I can swim.","explanation":"Ví dụ đúng: I can swim.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can swim.","is_correct":true},{"id":"b","text":"I can to swim.","is_correct":false}]},{"id":"lesson-zero-u10-03-q5","type":"true_false","phase":"language_focus","question":"Sau can, tài liệu dùng động từ nguyên thể.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 10; Bài tập Tiếng Anh 6 – Unit 5 & 6.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u10-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7","intro":{"title":"Present Simple","summary":"Hiện tại đơn dùng cho sự thật hiển nhiên, thói quen và sở thích. Khẳng định: S + V(s/es); phủ định: don''t/doesn''t + V nguyên thể; câu hỏi: do/does + S + V?. Dấu hiệu gồm every day, once/twice a week và các trạng từ tần suất.","rules":["I/you/we/they + V; he/she/it + V-s/es.","Phủ định: don''t/doesn''t + V nguyên thể.","Câu hỏi: Do/Does + S + V?","Trạng từ tần suất thường đứng trước động từ thường, sau to be; tài liệu còn nêu vị trí sau can."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u11-01-q1","type":"multiple_choice","phase":"pre_task","question":"Hiện tại đơn dùng cho sự thật hiển nhiên, thói quen và sở thích. Khẳng định: S + V(s/es); phủ định: don''t/doesn''t + V nguyên thể; câu hỏi: do/does + S + V?. Dấu hiệu gồm every day, once/twice a week và các trạng từ tần suất.\n\nQuy tắc cần nhớ:\n• I/you/we/they + V; he/she/it + V-s/es.\n• Phủ định: don''t/doesn''t + V nguyên thể.\n• Câu hỏi: Do/Does + S + V?\n• Trạng từ tần suất thường đứng trước động từ thường, sau to be; tài liệu còn nêu vị trí sau can.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"He watches TV every day.","explanation":"Ví dụ đúng: He watches TV every day.","hint":"I/you/we/they + V; he/she/it + V-s/es.","difficulty":1,"points":10,"options":[{"id":"a","text":"He watches TV every day.","is_correct":true},{"id":"b","text":"He watch TV every day.","is_correct":false}]},{"id":"lesson-zero-u11-01-q2","type":"true_false","phase":"language_focus","question":"Sau doesn''t, động từ trở về dạng nguyên thể.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u11-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: She ___ (read) books every day.","correct_answer":"reads","explanation":"Đáp án: reads","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u11-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi không đi học vào Chủ nhật.","correct_answer":"I don''t go to school on Sundays.","explanation":"Một cách viết theo bài học: I don''t go to school on Sundays.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u11-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7","intro":{"title":"Present Simple","summary":"Hiện tại đơn dùng cho sự thật hiển nhiên, thói quen và sở thích. Khẳng định: S + V(s/es); phủ định: don''t/doesn''t + V nguyên thể; câu hỏi: do/does + S + V?. Dấu hiệu gồm every day, once/twice a week và các trạng từ tần suất.","rules":["I/you/we/they + V; he/she/it + V-s/es.","Phủ định: don''t/doesn''t + V nguyên thể.","Câu hỏi: Do/Does + S + V?","Trạng từ tần suất thường đứng trước động từ thường, sau to be; tài liệu còn nêu vị trí sau can."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u11-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"Does he read books?","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"Does he read books?","is_correct":true},{"id":"b","text":"Does he reads books?","is_correct":false},{"id":"c","text":"Do he read books?","is_correct":false}]},{"id":"lesson-zero-u11-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: She ___ (read) books every day.","correct_answer":"reads","explanation":"Đáp án: reads","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u11-02-q3","type":"true_false","phase":"language_focus","question":"Sau doesn''t, động từ trở về dạng nguyên thể.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u11-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi không đi học vào Chủ nhật.","correct_answer":"I don''t go to school on Sundays.","explanation":"Đáp án mẫu: I don''t go to school on Sundays.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u11-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Present Simple.","correct_answer":"He watches TV every day.","explanation":"Câu đúng: He watches TV every day.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"He watches TV every day.","is_correct":true},{"id":"b","text":"He watch TV every day.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u11-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7","intro":{"title":"Present Simple","summary":"Hiện tại đơn dùng cho sự thật hiển nhiên, thói quen và sở thích. Khẳng định: S + V(s/es); phủ định: don''t/doesn''t + V nguyên thể; câu hỏi: do/does + S + V?. Dấu hiệu gồm every day, once/twice a week và các trạng từ tần suất.","rules":["I/you/we/they + V; he/she/it + V-s/es.","Phủ định: don''t/doesn''t + V nguyên thể.","Câu hỏi: Do/Does + S + V?","Trạng từ tần suất thường đứng trước động từ thường, sau to be; tài liệu còn nêu vị trí sau can."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u11-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Tôi thường thức dậy lúc 6 giờ 30.","correct_answer":"I often get up at 6:30.","explanation":"Đáp án mẫu: I often get up at 6:30.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u11-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền do/does: ___ Mary work on Saturdays?","correct_answer":"Does","explanation":"Đáp án: Does","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u11-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Trạng từ nào thể hiện tần suất 0% theo bảng của tài liệu?","correct_answer":"never","explanation":"Đáp án: never","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"never","is_correct":true},{"id":"b","text":"usually","is_correct":false},{"id":"c","text":"always","is_correct":false}]},{"id":"lesson-zero-u11-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Present Simple.","correct_answer":"He watches TV every day.","explanation":"Ví dụ đúng: He watches TV every day.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"He watches TV every day.","is_correct":true},{"id":"b","text":"He watch TV every day.","is_correct":false}]},{"id":"lesson-zero-u11-03-q5","type":"true_false","phase":"language_focus","question":"Sau doesn''t, động từ trở về dạng nguyên thể.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 11; Bài tập Tiếng Anh 6 – Unit 1 & 7.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u11-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3","intro":{"title":"Present Continuous","summary":"Hiện tại tiếp diễn có cấu trúc S + am/is/are + V-ing. Tài liệu dùng thì này cho hành động đang diễn ra, hành động khác thói quen hiện tại và kế hoạch chắc chắn đã sắp xếp. Dấu hiệu gồm now, at the moment, look!, listen!, today...","rules":["Khẳng định: S + am/is/are + V-ing.","Phủ định: am not/isn''t/aren''t + V-ing.","Câu hỏi: Am/Is/Are + S + V-ing?","Quy tắc thêm -ing: bỏ e; một số từ gấp đôi phụ âm; ie → y + ing."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u12-01-q1","type":"multiple_choice","phase":"pre_task","question":"Hiện tại tiếp diễn có cấu trúc S + am/is/are + V-ing. Tài liệu dùng thì này cho hành động đang diễn ra, hành động khác thói quen hiện tại và kế hoạch chắc chắn đã sắp xếp. Dấu hiệu gồm now, at the moment, look!, listen!, today...\n\nQuy tắc cần nhớ:\n• Khẳng định: S + am/is/are + V-ing.\n• Phủ định: am not/isn''t/aren''t + V-ing.\n• Câu hỏi: Am/Is/Are + S + V-ing?\n• Quy tắc thêm -ing: bỏ e; một số từ gấp đôi phụ âm; ie → y + ing.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"She is reading now.","explanation":"Ví dụ đúng: She is reading now.","hint":"Khẳng định: S + am/is/are + V-ing.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is reading now.","is_correct":true},{"id":"b","text":"She reading now.","is_correct":false}]},{"id":"lesson-zero-u12-01-q2","type":"true_false","phase":"language_focus","question":"Theo tài liệu, lie đổi thành lying.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u12-01-q3","type":"fill_blank","phase":"task_cycle","question":"Viết dạng -ing của make: ___","correct_answer":"making","explanation":"Đáp án: making","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u12-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ đang nói chuyện với bạn của họ bây giờ.","correct_answer":"They are talking with their friends now.","explanation":"Một cách viết theo bài học: They are talking with their friends now.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u12-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3","intro":{"title":"Present Continuous","summary":"Hiện tại tiếp diễn có cấu trúc S + am/is/are + V-ing. Tài liệu dùng thì này cho hành động đang diễn ra, hành động khác thói quen hiện tại và kế hoạch chắc chắn đã sắp xếp. Dấu hiệu gồm now, at the moment, look!, listen!, today...","rules":["Khẳng định: S + am/is/are + V-ing.","Phủ định: am not/isn''t/aren''t + V-ing.","Câu hỏi: Am/Is/Are + S + V-ing?","Quy tắc thêm -ing: bỏ e; một số từ gấp đôi phụ âm; ie → y + ing."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u12-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"We are studying English.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"We are studying English.","is_correct":true},{"id":"b","text":"We studying English.","is_correct":false},{"id":"c","text":"We is studying English.","is_correct":false}]},{"id":"lesson-zero-u12-02-q2","type":"fill_blank","phase":"task_cycle","question":"Viết dạng -ing của make: ___","correct_answer":"making","explanation":"Đáp án: making","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u12-02-q3","type":"true_false","phase":"language_focus","question":"Theo tài liệu, lie đổi thành lying.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u12-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Họ đang nói chuyện với bạn của họ bây giờ.","correct_answer":"They are talking with their friends now.","explanation":"Đáp án mẫu: They are talking with their friends now.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u12-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Present Continuous.","correct_answer":"She is reading now.","explanation":"Câu đúng: She is reading now.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is reading now.","is_correct":true},{"id":"b","text":"She reading now.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u12-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3","intro":{"title":"Present Continuous","summary":"Hiện tại tiếp diễn có cấu trúc S + am/is/are + V-ing. Tài liệu dùng thì này cho hành động đang diễn ra, hành động khác thói quen hiện tại và kế hoạch chắc chắn đã sắp xếp. Dấu hiệu gồm now, at the moment, look!, listen!, today...","rules":["Khẳng định: S + am/is/are + V-ing.","Phủ định: am not/isn''t/aren''t + V-ing.","Câu hỏi: Am/Is/Are + S + V-ing?","Quy tắc thêm -ing: bỏ e; một số từ gấp đôi phụ âm; ie → y + ing."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u12-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Anh ấy không chơi bóng đá bây giờ.","correct_answer":"He isn''t playing football now.","explanation":"Đáp án mẫu: He isn''t playing football now.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u12-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: The baby ___ sleeping at the moment.","correct_answer":"is","explanation":"Đáp án: is","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u12-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Dấu hiệu nào phù hợp với hiện tại tiếp diễn?","correct_answer":"at the moment","explanation":"Đáp án: at the moment","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"at the moment","is_correct":true},{"id":"b","text":"every Sunday","is_correct":false},{"id":"c","text":"once a week","is_correct":false}]},{"id":"lesson-zero-u12-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Present Continuous.","correct_answer":"She is reading now.","explanation":"Ví dụ đúng: She is reading now.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is reading now.","is_correct":true},{"id":"b","text":"She reading now.","is_correct":false}]},{"id":"lesson-zero-u12-03-q5","type":"true_false","phase":"language_focus","question":"Theo tài liệu, lie đổi thành lying.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 12; Bài tập Tiếng Anh 6 – Unit 1 & 3.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u12-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 13","intro":{"title":"Present Simple vs Present Continuous","summary":"Tài liệu đối chiếu hiện tại đơn và hiện tại tiếp diễn: hiện tại đơn dùng cho sự thật, thói quen, sở thích và lịch trình; hiện tại tiếp diễn dùng cho việc đang xảy ra, việc tạm thời khác thói quen và kế hoạch đã sắp xếp.","rules":["Present Simple: S + V(s/es); dấu hiệu always, usually, often, every day...","Present Continuous: S + am/is/are + V-ing; dấu hiệu now, at the moment, today, look!, listen!...","Tài liệu nêu một số động từ thường không dùng ở tiếp diễn: be, like, love, hate, want, need, understand, know, have."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u13-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu đối chiếu hiện tại đơn và hiện tại tiếp diễn: hiện tại đơn dùng cho sự thật, thói quen, sở thích và lịch trình; hiện tại tiếp diễn dùng cho việc đang xảy ra, việc tạm thời khác thói quen và kế hoạch đã sắp xếp.\n\nQuy tắc cần nhớ:\n• Present Simple: S + V(s/es); dấu hiệu always, usually, often, every day...\n• Present Continuous: S + am/is/are + V-ing; dấu hiệu now, at the moment, today, look!, listen!...\n• Tài liệu nêu một số động từ thường không dùng ở tiếp diễn: be, like, love, hate, want, need, understand, know, have.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"I often get up at 6:30. Today I am getting up at 7:30.","explanation":"Ví dụ đúng: I often get up at 6:30. Today I am getting up at 7:30.","hint":"Present Simple: S + V(s/es); dấu hiệu always, usually, often, every day...","difficulty":1,"points":10,"options":[{"id":"a","text":"I often get up at 6:30. Today I am getting up at 7:30.","is_correct":true},{"id":"b","text":"I am often get up at 6:30.","is_correct":false}]},{"id":"lesson-zero-u13-01-q2","type":"true_false","phase":"language_focus","question":"''Now'' là dấu hiệu thường dùng với hiện tại tiếp diễn.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 13.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u13-01-q3","type":"fill_blank","phase":"task_cycle","question":"Chọn dạng đúng: Look! It ___ (snow).","correct_answer":"is snowing","explanation":"Đáp án: is snowing","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u13-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Bố tôi đi làm lúc 6 giờ mỗi ngày.","correct_answer":"My dad finishes work at 6 p.m. every day.","explanation":"Một cách viết theo bài học: My dad finishes work at 6 p.m. every day.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u13-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 13","intro":{"title":"Present Simple vs Present Continuous","summary":"Tài liệu đối chiếu hiện tại đơn và hiện tại tiếp diễn: hiện tại đơn dùng cho sự thật, thói quen, sở thích và lịch trình; hiện tại tiếp diễn dùng cho việc đang xảy ra, việc tạm thời khác thói quen và kế hoạch đã sắp xếp.","rules":["Present Simple: S + V(s/es); dấu hiệu always, usually, often, every day...","Present Continuous: S + am/is/are + V-ing; dấu hiệu now, at the moment, today, look!, listen!...","Tài liệu nêu một số động từ thường không dùng ở tiếp diễn: be, like, love, hate, want, need, understand, know, have."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u13-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu phù hợp với thói quen.","correct_answer":"They play tennis on Fridays.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 13.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"They play tennis on Fridays.","is_correct":true},{"id":"b","text":"They are playing tennis on Fridays every week.","is_correct":false},{"id":"c","text":"They is play tennis.","is_correct":false}]},{"id":"lesson-zero-u13-02-q2","type":"fill_blank","phase":"task_cycle","question":"Chọn dạng đúng: Look! It ___ (snow).","correct_answer":"is snowing","explanation":"Đáp án: is snowing","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u13-02-q3","type":"true_false","phase":"language_focus","question":"''Now'' là dấu hiệu thường dùng với hiện tại tiếp diễn.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u13-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Bố tôi đi làm lúc 6 giờ mỗi ngày.","correct_answer":"My dad finishes work at 6 p.m. every day.","explanation":"Đáp án mẫu: My dad finishes work at 6 p.m. every day.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u13-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Present Simple vs Present Continuous.","correct_answer":"I often get up at 6:30. Today I am getting up at 7:30.","explanation":"Câu đúng: I often get up at 6:30. Today I am getting up at 7:30.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I often get up at 6:30. Today I am getting up at 7:30.","is_correct":true},{"id":"b","text":"I am often get up at 6:30.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u13-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 13","intro":{"title":"Present Simple vs Present Continuous","summary":"Tài liệu đối chiếu hiện tại đơn và hiện tại tiếp diễn: hiện tại đơn dùng cho sự thật, thói quen, sở thích và lịch trình; hiện tại tiếp diễn dùng cho việc đang xảy ra, việc tạm thời khác thói quen và kế hoạch đã sắp xếp.","rules":["Present Simple: S + V(s/es); dấu hiệu always, usually, often, every day...","Present Continuous: S + am/is/are + V-ing; dấu hiệu now, at the moment, today, look!, listen!...","Tài liệu nêu một số động từ thường không dùng ở tiếp diễn: be, like, love, hate, want, need, understand, know, have."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u13-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Tôi đang đi đến thư viện bây giờ.","correct_answer":"I am going to the library now.","explanation":"Đáp án mẫu: I am going to the library now.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u13-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: My grandparents ___ (live) in Hong Kong.","correct_answer":"live","explanation":"Đáp án: live","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u13-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Câu nào mô tả hành động đang xảy ra?","correct_answer":"Kathy is studying now.","explanation":"Đáp án: Kathy is studying now.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Kathy is studying now.","is_correct":true},{"id":"b","text":"Kathy studies every day.","is_correct":false},{"id":"c","text":"Kathy study now.","is_correct":false}]},{"id":"lesson-zero-u13-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Present Simple vs Present Continuous.","correct_answer":"I often get up at 6:30. Today I am getting up at 7:30.","explanation":"Ví dụ đúng: I often get up at 6:30. Today I am getting up at 7:30.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"I often get up at 6:30. Today I am getting up at 7:30.","is_correct":true},{"id":"b","text":"I am often get up at 6:30.","is_correct":false}]},{"id":"lesson-zero-u13-03-q5","type":"true_false","phase":"language_focus","question":"''Now'' là dấu hiệu thường dùng với hiện tại tiếp diễn.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 13.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u13-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 14","intro":{"title":"Countable and Uncountable Nouns","summary":"Danh từ đếm được có thể dùng số đếm, có số ít/số nhiều và số ít có thể đi với a/an. Danh từ không đếm được không đi với a/an hay số đếm và thường đi với some, any, little, much; tài liệu dùng động từ số ít với loại này.","rules":["Countable: one desk, two apples; số ít có thể dùng a/an.","Uncountable: sugar, rice, water, information; không dùng a/an.","some thường gặp trong câu khẳng định; any thường gặp trong phủ định/câu hỏi trong bài tập của tài liệu.","Danh từ không đếm được dùng động từ số ít."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u14-01-q1","type":"multiple_choice","phase":"pre_task","question":"Danh từ đếm được có thể dùng số đếm, có số ít/số nhiều và số ít có thể đi với a/an. Danh từ không đếm được không đi với a/an hay số đếm và thường đi với some, any, little, much; tài liệu dùng động từ số ít với loại này.\n\nQuy tắc cần nhớ:\n• Countable: one desk, two apples; số ít có thể dùng a/an.\n• Uncountable: sugar, rice, water, information; không dùng a/an.\n• some thường gặp trong câu khẳng định; any thường gặp trong phủ định/câu hỏi trong bài tập của tài liệu.\n• Danh từ không đếm được dùng động từ số ít.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"There is some milk in the fridge.","explanation":"Ví dụ đúng: There is some milk in the fridge.","hint":"Countable: one desk, two apples; số ít có thể dùng a/an.","difficulty":1,"points":10,"options":[{"id":"a","text":"There is some milk in the fridge.","is_correct":true},{"id":"b","text":"There are two milks in the fridge.","is_correct":false}]},{"id":"lesson-zero-u14-01-q2","type":"true_false","phase":"language_focus","question":"Theo tài liệu, information là danh từ không đếm được.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 14.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u14-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền some/any: I don''t have ___ money.","correct_answer":"any","explanation":"Đáp án: any","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u14-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi cần một ít nước.","correct_answer":"I need some water.","explanation":"Một cách viết theo bài học: I need some water.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u14-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 14","intro":{"title":"Countable and Uncountable Nouns","summary":"Danh từ đếm được có thể dùng số đếm, có số ít/số nhiều và số ít có thể đi với a/an. Danh từ không đếm được không đi với a/an hay số đếm và thường đi với some, any, little, much; tài liệu dùng động từ số ít với loại này.","rules":["Countable: one desk, two apples; số ít có thể dùng a/an.","Uncountable: sugar, rice, water, information; không dùng a/an.","some thường gặp trong câu khẳng định; any thường gặp trong phủ định/câu hỏi trong bài tập của tài liệu.","Danh từ không đếm được dùng động từ số ít."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u14-02-q1","type":"multiple_choice","phase":"pre_task","question":"Từ nào là danh từ không đếm được trong tài liệu?","correct_answer":"rice","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 14.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"rice","is_correct":true},{"id":"b","text":"apple","is_correct":false},{"id":"c","text":"bus","is_correct":false}]},{"id":"lesson-zero-u14-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền some/any: I don''t have ___ money.","correct_answer":"any","explanation":"Đáp án: any","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u14-02-q3","type":"true_false","phase":"language_focus","question":"Theo tài liệu, information là danh từ không đếm được.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u14-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi cần một ít nước.","correct_answer":"I need some water.","explanation":"Đáp án mẫu: I need some water.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u14-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Countable and Uncountable Nouns.","correct_answer":"There is some milk in the fridge.","explanation":"Câu đúng: There is some milk in the fridge.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"There is some milk in the fridge.","is_correct":true},{"id":"b","text":"There are two milks in the fridge.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u14-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 14","intro":{"title":"Countable and Uncountable Nouns","summary":"Danh từ đếm được có thể dùng số đếm, có số ít/số nhiều và số ít có thể đi với a/an. Danh từ không đếm được không đi với a/an hay số đếm và thường đi với some, any, little, much; tài liệu dùng động từ số ít với loại này.","rules":["Countable: one desk, two apples; số ít có thể dùng a/an.","Uncountable: sugar, rice, water, information; không dùng a/an.","some thường gặp trong câu khẳng định; any thường gặp trong phủ định/câu hỏi trong bài tập của tài liệu.","Danh từ không đếm được dùng động từ số ít."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u14-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Có trứng nào trong tủ lạnh không?","correct_answer":"Are there any eggs in the fridge?","explanation":"Đáp án mẫu: Are there any eggs in the fridge?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u14-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền a/an/some: There is ___ milk.","correct_answer":"some","explanation":"Đáp án: some","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u14-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn cụm đúng.","correct_answer":"some information","explanation":"Đáp án: some information","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"some information","is_correct":true},{"id":"b","text":"an information","is_correct":false},{"id":"c","text":"two informations","is_correct":false}]},{"id":"lesson-zero-u14-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Countable and Uncountable Nouns.","correct_answer":"There is some milk in the fridge.","explanation":"Ví dụ đúng: There is some milk in the fridge.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"There is some milk in the fridge.","is_correct":true},{"id":"b","text":"There are two milks in the fridge.","is_correct":false}]},{"id":"lesson-zero-u14-03-q5","type":"true_false","phase":"language_focus","question":"Theo tài liệu, information là danh từ không đếm được.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 14.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u14-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 15","intro":{"title":"Questions","summary":"Tài liệu giới thiệu các từ hỏi: who, what, where, when, why, which, whose, what time, how, how many/how much, how old, how long, how often, how far. Câu hỏi hiện tại đơn dùng do/does; với to be hoặc tiếp diễn dùng am/is/are theo cấu trúc tương ứng.","rules":["Who: ai; What: cái gì; Where: ở đâu; When: khi nào; Why: tại sao.","Which: cái nào; Whose: của ai; What time: mấy giờ.","How many/how much: bao nhiêu; How old: tuổi; How long: bao lâu; How often: tần suất; How far: khoảng cách."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u15-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu giới thiệu các từ hỏi: who, what, where, when, why, which, whose, what time, how, how many/how much, how old, how long, how often, how far. Câu hỏi hiện tại đơn dùng do/does; với to be hoặc tiếp diễn dùng am/is/are theo cấu trúc tương ứng.\n\nQuy tắc cần nhớ:\n• Who: ai; What: cái gì; Where: ở đâu; When: khi nào; Why: tại sao.\n• Which: cái nào; Whose: của ai; What time: mấy giờ.\n• How many/how much: bao nhiêu; How old: tuổi; How long: bao lâu; How often: tần suất; How far: khoảng cách.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"Where do you live?","explanation":"Ví dụ đúng: Where do you live?","hint":"Who: ai; What: cái gì; Where: ở đâu; When: khi nào; Why: tại sao.","difficulty":1,"points":10,"options":[{"id":"a","text":"Where do you live?","is_correct":true},{"id":"b","text":"Where you live?","is_correct":false}]},{"id":"lesson-zero-u15-01-q2","type":"true_false","phase":"language_focus","question":"Whose dùng để hỏi về sở hữu.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 15.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u15-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền từ hỏi: ___ old are you?","correct_answer":"How","explanation":"Đáp án: How","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u15-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Bạn sống ở đâu?","correct_answer":"Where do you live?","explanation":"Một cách viết theo bài học: Where do you live?","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u15-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 15","intro":{"title":"Questions","summary":"Tài liệu giới thiệu các từ hỏi: who, what, where, when, why, which, whose, what time, how, how many/how much, how old, how long, how often, how far. Câu hỏi hiện tại đơn dùng do/does; với to be hoặc tiếp diễn dùng am/is/are theo cấu trúc tương ứng.","rules":["Who: ai; What: cái gì; Where: ở đâu; When: khi nào; Why: tại sao.","Which: cái nào; Whose: của ai; What time: mấy giờ.","How many/how much: bao nhiêu; How old: tuổi; How long: bao lâu; How often: tần suất; How far: khoảng cách."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u15-02-q1","type":"multiple_choice","phase":"pre_task","question":"Từ hỏi nào dùng để hỏi lý do?","correct_answer":"Why","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 15.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"Why","is_correct":true},{"id":"b","text":"When","is_correct":false},{"id":"c","text":"Who","is_correct":false}]},{"id":"lesson-zero-u15-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền từ hỏi: ___ old are you?","correct_answer":"How","explanation":"Đáp án: How","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u15-02-q3","type":"true_false","phase":"language_focus","question":"Whose dùng để hỏi về sở hữu.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u15-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Bạn sống ở đâu?","correct_answer":"Where do you live?","explanation":"Đáp án mẫu: Where do you live?","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u15-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Questions.","correct_answer":"Where do you live?","explanation":"Câu đúng: Where do you live?","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"Where do you live?","is_correct":true},{"id":"b","text":"Where you live?","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u15-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 15","intro":{"title":"Questions","summary":"Tài liệu giới thiệu các từ hỏi: who, what, where, when, why, which, whose, what time, how, how many/how much, how old, how long, how often, how far. Câu hỏi hiện tại đơn dùng do/does; với to be hoặc tiếp diễn dùng am/is/are theo cấu trúc tương ứng.","rules":["Who: ai; What: cái gì; Where: ở đâu; When: khi nào; Why: tại sao.","Which: cái nào; Whose: của ai; What time: mấy giờ.","How many/how much: bao nhiêu; How old: tuổi; How long: bao lâu; How often: tần suất; How far: khoảng cách."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u15-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Trường bạn cách nhà bao xa?","correct_answer":"How far is your school from your house?","explanation":"Đáp án mẫu: How far is your school from your house?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u15-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền từ hỏi: ___ often do you play football?","correct_answer":"How","explanation":"Đáp án: How","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u15-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn câu hỏi về số lượng danh từ đếm được.","correct_answer":"How many students are there?","explanation":"Đáp án: How many students are there?","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"How many students are there?","is_correct":true},{"id":"b","text":"How much students are there?","is_correct":false},{"id":"c","text":"How far students are there?","is_correct":false}]},{"id":"lesson-zero-u15-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Questions.","correct_answer":"Where do you live?","explanation":"Ví dụ đúng: Where do you live?","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Where do you live?","is_correct":true},{"id":"b","text":"Where you live?","is_correct":false}]},{"id":"lesson-zero-u15-03-q5","type":"true_false","phase":"language_focus","question":"Whose dùng để hỏi về sở hữu.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 15.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u15-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 16","intro":{"title":"Pronouns","summary":"Unit 16 phân biệt đại từ chủ ngữ và đại từ tân ngữ. Đại từ chủ ngữ đứng đầu câu làm chủ ngữ; đại từ tân ngữ đứng sau động từ và nhận tác động: I→me, you→you, we→us, they→them, he→him, she→her, it→it.","rules":["Subject pronouns: I, you, we, they, he, she, it.","Object pronouns: me, you, us, them, him, her, it.","Đại từ tân ngữ đứng sau động từ: I like him; She loves him."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u16-01-q1","type":"multiple_choice","phase":"pre_task","question":"Unit 16 phân biệt đại từ chủ ngữ và đại từ tân ngữ. Đại từ chủ ngữ đứng đầu câu làm chủ ngữ; đại từ tân ngữ đứng sau động từ và nhận tác động: I→me, you→you, we→us, they→them, he→him, she→her, it→it.\n\nQuy tắc cần nhớ:\n• Subject pronouns: I, you, we, they, he, she, it.\n• Object pronouns: me, you, us, them, him, her, it.\n• Đại từ tân ngữ đứng sau động từ: I like him; She loves him.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"I can''t see Mary. I can''t see her.","explanation":"Ví dụ đúng: I can''t see Mary. I can''t see her.","hint":"Subject pronouns: I, you, we, they, he, she, it.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can''t see Mary. I can''t see her.","is_correct":true},{"id":"b","text":"I can''t see she.","is_correct":false}]},{"id":"lesson-zero-u16-01-q2","type":"true_false","phase":"language_focus","question":"Him là đại từ tân ngữ tương ứng với he.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 16.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u16-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền đại từ tân ngữ: Can you help Peter and Ann? Can you help ___?","correct_answer":"them","explanation":"Đáp án: them","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u16-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Hãy giúp tôi!","correct_answer":"Help me!","explanation":"Một cách viết theo bài học: Help me!","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u16-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 16","intro":{"title":"Pronouns","summary":"Unit 16 phân biệt đại từ chủ ngữ và đại từ tân ngữ. Đại từ chủ ngữ đứng đầu câu làm chủ ngữ; đại từ tân ngữ đứng sau động từ và nhận tác động: I→me, you→you, we→us, they→them, he→him, she→her, it→it.","rules":["Subject pronouns: I, you, we, they, he, she, it.","Object pronouns: me, you, us, them, him, her, it.","Đại từ tân ngữ đứng sau động từ: I like him; She loves him."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u16-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn đại từ tân ngữ của ''we''.","correct_answer":"us","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 16.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"us","is_correct":true},{"id":"b","text":"our","is_correct":false},{"id":"c","text":"we","is_correct":false}]},{"id":"lesson-zero-u16-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền đại từ tân ngữ: Can you help Peter and Ann? Can you help ___?","correct_answer":"them","explanation":"Đáp án: them","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u16-02-q3","type":"true_false","phase":"language_focus","question":"Him là đại từ tân ngữ tương ứng với he.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u16-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Hãy giúp tôi!","correct_answer":"Help me!","explanation":"Đáp án mẫu: Help me!","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u16-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Pronouns.","correct_answer":"I can''t see Mary. I can''t see her.","explanation":"Câu đúng: I can''t see Mary. I can''t see her.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can''t see Mary. I can''t see her.","is_correct":true},{"id":"b","text":"I can''t see she.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u16-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 16","intro":{"title":"Pronouns","summary":"Unit 16 phân biệt đại từ chủ ngữ và đại từ tân ngữ. Đại từ chủ ngữ đứng đầu câu làm chủ ngữ; đại từ tân ngữ đứng sau động từ và nhận tác động: I→me, you→you, we→us, they→them, he→him, she→her, it→it.","rules":["Subject pronouns: I, you, we, they, he, she, it.","Object pronouns: me, you, us, them, him, her, it.","Đại từ tân ngữ đứng sau động từ: I like him; She loves him."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u16-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Tôi thích cô ấy.","correct_answer":"I like her.","explanation":"Đáp án mẫu: I like her.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u16-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: Drink your apple juice! Drink ___.","correct_answer":"it","explanation":"Đáp án: it","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u16-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn câu đúng.","correct_answer":"Come with us.","explanation":"Đáp án: Come with us.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Come with us.","is_correct":true},{"id":"b","text":"Come with we.","is_correct":false},{"id":"c","text":"Come with our.","is_correct":false}]},{"id":"lesson-zero-u16-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Pronouns.","correct_answer":"I can''t see Mary. I can''t see her.","explanation":"Ví dụ đúng: I can''t see Mary. I can''t see her.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"I can''t see Mary. I can''t see her.","is_correct":true},{"id":"b","text":"I can''t see she.","is_correct":false}]},{"id":"lesson-zero-u16-03-q5","type":"true_false","phase":"language_focus","question":"Him là đại từ tân ngữ tương ứng với he.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 16.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u16-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8","intro":{"title":"Past Simple","summary":"Quá khứ đơn dùng cho hành động/sự việc đã xảy ra và chấm dứt trong quá khứ. Với to be dùng was/were; với động từ thường dùng V-ed hoặc dạng bất quy tắc. Phủ định dùng didn''t + V nguyên thể; câu hỏi dùng Did + S + V?.","rules":["I/he/she/it + was; you/we/they + were.","Động từ có quy tắc thường thêm -ed; tài liệu nêu các quy tắc với e, phụ âm cuối và y.","Phủ định: didn''t + V nguyên thể.","Câu hỏi: Did + S + V?; dấu hiệu: yesterday, last..., ...ago."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u17-01-q1","type":"multiple_choice","phase":"pre_task","question":"Quá khứ đơn dùng cho hành động/sự việc đã xảy ra và chấm dứt trong quá khứ. Với to be dùng was/were; với động từ thường dùng V-ed hoặc dạng bất quy tắc. Phủ định dùng didn''t + V nguyên thể; câu hỏi dùng Did + S + V?.\n\nQuy tắc cần nhớ:\n• I/he/she/it + was; you/we/they + were.\n• Động từ có quy tắc thường thêm -ed; tài liệu nêu các quy tắc với e, phụ âm cuối và y.\n• Phủ định: didn''t + V nguyên thể.\n• Câu hỏi: Did + S + V?; dấu hiệu: yesterday, last..., ...ago.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"He went to school yesterday.","explanation":"Ví dụ đúng: He went to school yesterday.","hint":"I/he/she/it + was; you/we/they + were.","difficulty":1,"points":10,"options":[{"id":"a","text":"He went to school yesterday.","is_correct":true},{"id":"b","text":"He did went to school yesterday.","is_correct":false}]},{"id":"lesson-zero-u17-01-q2","type":"true_false","phase":"language_focus","question":"Sau didn''t, dùng động từ nguyên thể.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u17-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền dạng quá khứ của go: ___","correct_answer":"went","explanation":"Đáp án: went","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u17-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi đã không đi xem phim hôm qua.","correct_answer":"I didn''t go to the cinema yesterday.","explanation":"Một cách viết theo bài học: I didn''t go to the cinema yesterday.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u17-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8","intro":{"title":"Past Simple","summary":"Quá khứ đơn dùng cho hành động/sự việc đã xảy ra và chấm dứt trong quá khứ. Với to be dùng was/were; với động từ thường dùng V-ed hoặc dạng bất quy tắc. Phủ định dùng didn''t + V nguyên thể; câu hỏi dùng Did + S + V?.","rules":["I/he/she/it + was; you/we/they + were.","Động từ có quy tắc thường thêm -ed; tài liệu nêu các quy tắc với e, phụ âm cuối và y.","Phủ định: didn''t + V nguyên thể.","Câu hỏi: Did + S + V?; dấu hiệu: yesterday, last..., ...ago."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u17-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn dạng đúng: They ___ at home yesterday.","correct_answer":"were","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"were","is_correct":true},{"id":"b","text":"was","is_correct":false},{"id":"c","text":"are","is_correct":false}]},{"id":"lesson-zero-u17-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng quá khứ của go: ___","correct_answer":"went","explanation":"Đáp án: went","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u17-02-q3","type":"true_false","phase":"language_focus","question":"Sau didn''t, dùng động từ nguyên thể.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u17-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi đã không đi xem phim hôm qua.","correct_answer":"I didn''t go to the cinema yesterday.","explanation":"Đáp án mẫu: I didn''t go to the cinema yesterday.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u17-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Past Simple.","correct_answer":"He went to school yesterday.","explanation":"Câu đúng: He went to school yesterday.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"He went to school yesterday.","is_correct":true},{"id":"b","text":"He did went to school yesterday.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u17-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8","intro":{"title":"Past Simple","summary":"Quá khứ đơn dùng cho hành động/sự việc đã xảy ra và chấm dứt trong quá khứ. Với to be dùng was/were; với động từ thường dùng V-ed hoặc dạng bất quy tắc. Phủ định dùng didn''t + V nguyên thể; câu hỏi dùng Did + S + V?.","rules":["I/he/she/it + was; you/we/they + were.","Động từ có quy tắc thường thêm -ed; tài liệu nêu các quy tắc với e, phụ âm cuối và y.","Phủ định: didn''t + V nguyên thể.","Câu hỏi: Did + S + V?; dấu hiệu: yesterday, last..., ...ago."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u17-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Bạn có làm bài tập về nhà hôm qua không?","correct_answer":"Did you do your homework yesterday?","explanation":"Đáp án mẫu: Did you do your homework yesterday?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u17-03-q2","type":"fill_blank","phase":"task_cycle","question":"Viết quá khứ của study: ___","correct_answer":"studied","explanation":"Đáp án: studied","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u17-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Dấu hiệu nào phù hợp với quá khứ đơn?","correct_answer":"last night","explanation":"Đáp án: last night","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"last night","is_correct":true},{"id":"b","text":"now","is_correct":false},{"id":"c","text":"every day","is_correct":false}]},{"id":"lesson-zero-u17-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Past Simple.","correct_answer":"He went to school yesterday.","explanation":"Ví dụ đúng: He went to school yesterday.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"He went to school yesterday.","is_correct":true},{"id":"b","text":"He did went to school yesterday.","is_correct":false}]},{"id":"lesson-zero-u17-03-q5","type":"true_false","phase":"language_focus","question":"Sau didn''t, dùng động từ nguyên thể.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 17; Bài tập Tiếng Anh 6 – Unit 8.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u17-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10","intro":{"title":"Future: Be Going To / Will","summary":"Tài liệu phân biệt be going to và will. Be going to dùng cho kế hoạch/dự định có trước và dự đoán dựa trên dấu hiệu; will dùng cho quyết định tại lúc nói và dự đoán/chuyện tương lai chưa chắc chắn. Dấu hiệu thời gian gồm tomorrow, tonight, next week/month/year.","rules":["be going to: S + am/is/are + going to + V.","will: S + will + V; phủ định will not/won''t.","Be going to cho dự định và dự đoán có dấu hiệu.","Will cho quyết định tức thời và phỏng đoán; tài liệu gắn với think, hope, believe, perhaps..."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u18-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu phân biệt be going to và will. Be going to dùng cho kế hoạch/dự định có trước và dự đoán dựa trên dấu hiệu; will dùng cho quyết định tại lúc nói và dự đoán/chuyện tương lai chưa chắc chắn. Dấu hiệu thời gian gồm tomorrow, tonight, next week/month/year.\n\nQuy tắc cần nhớ:\n• be going to: S + am/is/are + going to + V.\n• will: S + will + V; phủ định will not/won''t.\n• Be going to cho dự định và dự đoán có dấu hiệu.\n• Will cho quyết định tức thời và phỏng đoán; tài liệu gắn với think, hope, believe, perhaps...\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"The phone is ringing. I''ll answer it.","explanation":"Ví dụ đúng: The phone is ringing. I''ll answer it.","hint":"be going to: S + am/is/are + going to + V.","difficulty":1,"points":10,"options":[{"id":"a","text":"The phone is ringing. I''ll answer it.","is_correct":true},{"id":"b","text":"The phone is ringing. I going to answer it.","is_correct":false}]},{"id":"lesson-zero-u18-01-q2","type":"true_false","phase":"language_focus","question":"Tài liệu dùng be going to cho kế hoạch đã có trước.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u18-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền: It is cloudy. It ___ rain.","correct_answer":"is going to","explanation":"Đáp án: is going to","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u18-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi sẽ đến thăm ông bà vào tuần tới.","correct_answer":"I''m going to visit my grandparents next week.","explanation":"Một cách viết theo bài học: I''m going to visit my grandparents next week.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u18-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10","intro":{"title":"Future: Be Going To / Will","summary":"Tài liệu phân biệt be going to và will. Be going to dùng cho kế hoạch/dự định có trước và dự đoán dựa trên dấu hiệu; will dùng cho quyết định tại lúc nói và dự đoán/chuyện tương lai chưa chắc chắn. Dấu hiệu thời gian gồm tomorrow, tonight, next week/month/year.","rules":["be going to: S + am/is/are + going to + V.","will: S + will + V; phủ định will not/won''t.","Be going to cho dự định và dự đoán có dấu hiệu.","Will cho quyết định tức thời và phỏng đoán; tài liệu gắn với think, hope, believe, perhaps..."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u18-02-q1","type":"multiple_choice","phase":"pre_task","question":"Điện thoại đang reo và bạn quyết định ngay. Chọn câu phù hợp.","correct_answer":"I''ll answer it.","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I''ll answer it.","is_correct":true},{"id":"b","text":"I''m answer it.","is_correct":false},{"id":"c","text":"I answering it.","is_correct":false}]},{"id":"lesson-zero-u18-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: It is cloudy. It ___ rain.","correct_answer":"is going to","explanation":"Đáp án: is going to","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u18-02-q3","type":"true_false","phase":"language_focus","question":"Tài liệu dùng be going to cho kế hoạch đã có trước.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u18-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi sẽ đến thăm ông bà vào tuần tới.","correct_answer":"I''m going to visit my grandparents next week.","explanation":"Đáp án mẫu: I''m going to visit my grandparents next week.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u18-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Future: Be Going To / Will.","correct_answer":"The phone is ringing. I''ll answer it.","explanation":"Câu đúng: The phone is ringing. I''ll answer it.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"The phone is ringing. I''ll answer it.","is_correct":true},{"id":"b","text":"The phone is ringing. I going to answer it.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u18-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10","intro":{"title":"Future: Be Going To / Will","summary":"Tài liệu phân biệt be going to và will. Be going to dùng cho kế hoạch/dự định có trước và dự đoán dựa trên dấu hiệu; will dùng cho quyết định tại lúc nói và dự đoán/chuyện tương lai chưa chắc chắn. Dấu hiệu thời gian gồm tomorrow, tonight, next week/month/year.","rules":["be going to: S + am/is/are + going to + V.","will: S + will + V; phủ định will not/won''t.","Be going to cho dự định và dự đoán có dấu hiệu.","Will cho quyết định tức thời và phỏng đoán; tài liệu gắn với think, hope, believe, perhaps..."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u18-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Tôi nghĩ đội của chúng ta sẽ thắng.","correct_answer":"I think our team will win.","explanation":"Đáp án mẫu: I think our team will win.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u18-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền will/be going to: Perhaps I ___ go to Spain one day.","correct_answer":"will","explanation":"Đáp án: will","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u18-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn câu mô tả dự đoán có dấu hiệu rõ.","correct_answer":"Look at the clouds. It''s going to rain.","explanation":"Đáp án: Look at the clouds. It''s going to rain.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Look at the clouds. It''s going to rain.","is_correct":true},{"id":"b","text":"Perhaps it will rain next year.","is_correct":false},{"id":"c","text":"I go to rain.","is_correct":false}]},{"id":"lesson-zero-u18-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Future: Be Going To / Will.","correct_answer":"The phone is ringing. I''ll answer it.","explanation":"Ví dụ đúng: The phone is ringing. I''ll answer it.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"The phone is ringing. I''ll answer it.","is_correct":true},{"id":"b","text":"The phone is ringing. I going to answer it.","is_correct":false}]},{"id":"lesson-zero-u18-03-q5","type":"true_false","phase":"language_focus","question":"Tài liệu dùng be going to cho kế hoạch đã có trước.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 18; Bài tập Tiếng Anh 6 – Unit 6 & 10.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u18-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5","intro":{"title":"Adjectives","summary":"Tính từ có thể đứng sau to be, đứng trước danh từ, hoặc sau các linking verbs như smell, taste, sound, look, feel, become/get/turn, seem. Tài liệu còn trình bày trật tự nhiều tính từ: opinion, size, age, shape, color, origin, material, purpose. Bài tập Tiếng Anh 6 mở rộng với so sánh hơn và so sánh nhất.","rules":["Sau to be: He is hungry.","Trước danh từ: a beautiful girl.","Sau linking verb: You look tired; the food tastes good.","Trật tự: opinion → size → age → shape → color → origin → material → purpose.","Mở rộng từ BTTA6: comparative và superlative."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u19-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tính từ có thể đứng sau to be, đứng trước danh từ, hoặc sau các linking verbs như smell, taste, sound, look, feel, become/get/turn, seem. Tài liệu còn trình bày trật tự nhiều tính từ: opinion, size, age, shape, color, origin, material, purpose. Bài tập Tiếng Anh 6 mở rộng với so sánh hơn và so sánh nhất.\n\nQuy tắc cần nhớ:\n• Sau to be: He is hungry.\n• Trước danh từ: a beautiful girl.\n• Sau linking verb: You look tired; the food tastes good.\n• Trật tự: opinion → size → age → shape → color → origin → material → purpose.\n• Mở rộng từ BTTA6: comparative và superlative.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"She is a beautiful girl.","explanation":"Ví dụ đúng: She is a beautiful girl.","hint":"Sau to be: He is hungry.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a beautiful girl.","is_correct":true},{"id":"b","text":"She is a beautifully girl.","is_correct":false}]},{"id":"lesson-zero-u19-01-q2","type":"true_false","phase":"language_focus","question":"Sau linking verb ''look'', tài liệu dùng tính từ.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u19-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền tính từ phù hợp: The dog looks ___. (happy/happily)","correct_answer":"happy","explanation":"Đáp án: happy","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u19-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đây là một ngôi nhà cũ.","correct_answer":"This is an old house.","explanation":"Một cách viết theo bài học: This is an old house.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u19-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5","intro":{"title":"Adjectives","summary":"Tính từ có thể đứng sau to be, đứng trước danh từ, hoặc sau các linking verbs như smell, taste, sound, look, feel, become/get/turn, seem. Tài liệu còn trình bày trật tự nhiều tính từ: opinion, size, age, shape, color, origin, material, purpose. Bài tập Tiếng Anh 6 mở rộng với so sánh hơn và so sánh nhất.","rules":["Sau to be: He is hungry.","Trước danh từ: a beautiful girl.","Sau linking verb: You look tired; the food tastes good.","Trật tự: opinion → size → age → shape → color → origin → material → purpose.","Mở rộng từ BTTA6: comparative và superlative."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u19-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn cụm đúng theo trật tự tính từ cơ bản.","correct_answer":"a beautiful big old house","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"a beautiful big old house","is_correct":true},{"id":"b","text":"an old big beautiful house","is_correct":false},{"id":"c","text":"a big old beautiful house","is_correct":false}]},{"id":"lesson-zero-u19-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền tính từ phù hợp: The dog looks ___. (happy/happily)","correct_answer":"happy","explanation":"Đáp án: happy","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u19-02-q3","type":"true_false","phase":"language_focus","question":"Sau linking verb ''look'', tài liệu dùng tính từ.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u19-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Đây là một ngôi nhà cũ.","correct_answer":"This is an old house.","explanation":"Đáp án mẫu: This is an old house.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u19-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Adjectives.","correct_answer":"She is a beautiful girl.","explanation":"Câu đúng: She is a beautiful girl.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a beautiful girl.","is_correct":true},{"id":"b","text":"She is a beautifully girl.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u19-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5","intro":{"title":"Adjectives","summary":"Tính từ có thể đứng sau to be, đứng trước danh từ, hoặc sau các linking verbs như smell, taste, sound, look, feel, become/get/turn, seem. Tài liệu còn trình bày trật tự nhiều tính từ: opinion, size, age, shape, color, origin, material, purpose. Bài tập Tiếng Anh 6 mở rộng với so sánh hơn và so sánh nhất.","rules":["Sau to be: He is hungry.","Trước danh từ: a beautiful girl.","Sau linking verb: You look tired; the food tastes good.","Trật tự: opinion → size → age → shape → color → origin → material → purpose.","Mở rộng từ BTTA6: comparative và superlative."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u19-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Thành phố này ồn ào.","correct_answer":"This city is noisy.","explanation":"Đáp án mẫu: This city is noisy.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u19-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng so sánh hơn: Ho Chi Minh City is ___ than Da Nang. (polluted)","correct_answer":"more polluted","explanation":"Đáp án: more polluted","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u19-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn dạng so sánh nhất đúng.","correct_answer":"the highest","explanation":"Đáp án: the highest","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"the highest","is_correct":true},{"id":"b","text":"higher","is_correct":false},{"id":"c","text":"most high","is_correct":false}]},{"id":"lesson-zero-u19-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Adjectives.","correct_answer":"She is a beautiful girl.","explanation":"Ví dụ đúng: She is a beautiful girl.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"She is a beautiful girl.","is_correct":true},{"id":"b","text":"She is a beautifully girl.","is_correct":false}]},{"id":"lesson-zero-u19-03-q5","type":"true_false","phase":"language_focus","question":"Sau linking verb ''look'', tài liệu dùng tính từ.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 19; Bài tập Tiếng Anh 6 – Unit 3, 4 & 5.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u19-03';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 20","intro":{"title":"Adverbs","summary":"Tài liệu chia trạng từ thành các nhóm như tần suất, cách thức, mức độ, thời gian và nơi chốn. Trạng từ cách thức thường bổ nghĩa cho động từ; nhiều từ được tạo bằng adjective + -ly, nhưng có các dạng đặc biệt như good→well và các từ giữ nguyên như fast, hard, late, early.","rules":["Manner: careful→carefully, quiet→quietly, quick→quickly.","Đặc biệt: good→well; fast/hard/late/early giữ nguyên trong các ví dụ của tài liệu.","Frequency: never, rarely, sometimes, often, usually, always...","Time: yesterday, today, tomorrow; place: here, there, outside, inside; degree: very, really, quite/rather, extremely."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u20-01-q1","type":"multiple_choice","phase":"pre_task","question":"Tài liệu chia trạng từ thành các nhóm như tần suất, cách thức, mức độ, thời gian và nơi chốn. Trạng từ cách thức thường bổ nghĩa cho động từ; nhiều từ được tạo bằng adjective + -ly, nhưng có các dạng đặc biệt như good→well và các từ giữ nguyên như fast, hard, late, early.\n\nQuy tắc cần nhớ:\n• Manner: careful→carefully, quiet→quietly, quick→quickly.\n• Đặc biệt: good→well; fast/hard/late/early giữ nguyên trong các ví dụ của tài liệu.\n• Frequency: never, rarely, sometimes, often, usually, always...\n• Time: yesterday, today, tomorrow; place: here, there, outside, inside; degree: very, really, quite/rather, extremely.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"He drives carefully.","explanation":"Ví dụ đúng: He drives carefully.","hint":"Manner: careful→carefully, quiet→quietly, quick→quickly.","difficulty":1,"points":10,"options":[{"id":"a","text":"He drives carefully.","is_correct":true},{"id":"b","text":"He drives careful.","is_correct":false}]},{"id":"lesson-zero-u20-01-q2","type":"true_false","phase":"language_focus","question":"Fast có thể giữ nguyên khi dùng làm trạng từ theo tài liệu.","correct_answer":"True","explanation":"Dựa trên nội dung của Ngữ pháp Tiếng Anh – Unit 20.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u20-01-q3","type":"fill_blank","phase":"task_cycle","question":"Đổi good thành trạng từ: ___","correct_answer":"well","explanation":"Đáp án: well","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u20-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Cô ấy hát rất hay.","correct_answer":"She sings very well.","explanation":"Một cách viết theo bài học: She sings very well.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u20-01';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 20","intro":{"title":"Adverbs","summary":"Tài liệu chia trạng từ thành các nhóm như tần suất, cách thức, mức độ, thời gian và nơi chốn. Trạng từ cách thức thường bổ nghĩa cho động từ; nhiều từ được tạo bằng adjective + -ly, nhưng có các dạng đặc biệt như good→well và các từ giữ nguyên như fast, hard, late, early.","rules":["Manner: careful→carefully, quiet→quietly, quick→quickly.","Đặc biệt: good→well; fast/hard/late/early giữ nguyên trong các ví dụ của tài liệu.","Frequency: never, rarely, sometimes, often, usually, always...","Time: yesterday, today, tomorrow; place: here, there, outside, inside; degree: very, really, quite/rather, extremely."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u20-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn từ đúng: I opened the door ___.","correct_answer":"silently","explanation":"Đáp án phù hợp với quy tắc trong Ngữ pháp Tiếng Anh – Unit 20.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"silently","is_correct":true},{"id":"b","text":"silent","is_correct":false},{"id":"c","text":"silence","is_correct":false}]},{"id":"lesson-zero-u20-02-q2","type":"fill_blank","phase":"task_cycle","question":"Đổi good thành trạng từ: ___","correct_answer":"well","explanation":"Đáp án: well","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u20-02-q3","type":"true_false","phase":"language_focus","question":"Fast có thể giữ nguyên khi dùng làm trạng từ theo tài liệu.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u20-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Cô ấy hát rất hay.","correct_answer":"She sings very well.","explanation":"Đáp án mẫu: She sings very well.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u20-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Adverbs.","correct_answer":"He drives carefully.","explanation":"Câu đúng: He drives carefully.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"He drives carefully.","is_correct":true},{"id":"b","text":"He drives careful.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u20-02';
UPDATE lessons SET content='{"source_basis":"Ngữ pháp Tiếng Anh – Unit 20","intro":{"title":"Adverbs","summary":"Tài liệu chia trạng từ thành các nhóm như tần suất, cách thức, mức độ, thời gian và nơi chốn. Trạng từ cách thức thường bổ nghĩa cho động từ; nhiều từ được tạo bằng adjective + -ly, nhưng có các dạng đặc biệt như good→well và các từ giữ nguyên như fast, hard, late, early.","rules":["Manner: careful→carefully, quiet→quietly, quick→quickly.","Đặc biệt: good→well; fast/hard/late/early giữ nguyên trong các ví dụ của tài liệu.","Frequency: never, rarely, sometimes, often, usually, always...","Time: yesterday, today, tomorrow; place: here, there, outside, inside; degree: very, really, quite/rather, extremely."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u20-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Anh ấy chạy rất nhanh.","correct_answer":"He runs fast.","explanation":"Đáp án mẫu: He runs fast.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u20-03-q2","type":"fill_blank","phase":"task_cycle","question":"Đổi happy thành trạng từ: ___","correct_answer":"happily","explanation":"Đáp án: happily","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u20-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn câu đúng.","correct_answer":"My mother cooks well.","explanation":"Đáp án: My mother cooks well.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"My mother cooks well.","is_correct":true},{"id":"b","text":"My mother cooks good.","is_correct":false},{"id":"c","text":"My mother well cooks.","is_correct":false}]},{"id":"lesson-zero-u20-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Adverbs.","correct_answer":"He drives carefully.","explanation":"Ví dụ đúng: He drives carefully.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"He drives carefully.","is_correct":true},{"id":"b","text":"He drives careful.","is_correct":false}]},{"id":"lesson-zero-u20-03-q5","type":"true_false","phase":"language_focus","question":"Fast có thể giữ nguyên khi dùng làm trạng từ theo tài liệu.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Ngữ pháp Tiếng Anh – Unit 20.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u20-03';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 9 Cities of the World","intro":{"title":"Present Perfect","summary":"Unit 9 luyện hiện tại hoàn thành với have/has + past participle, các từ ever, yet, already, for, since và đối chiếu với quá khứ đơn. Bài tập có dạng ''Have you ever...?'', ''I haven''t ... yet'', ''since 2001'' và ''for three years''.","rules":["Cấu trúc luyện trong Unit 9: have/has + past participle.","ever/never thường dùng khi nói trải nghiệm; already/yet dùng với việc đã/chưa hoàn thành trong các bài tập.","for + khoảng thời gian; since + mốc thời gian.","Quá khứ đơn dùng khi thời điểm quá khứ xác định được nêu rõ."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u21-01-q1","type":"multiple_choice","phase":"pre_task","question":"Unit 9 luyện hiện tại hoàn thành với have/has + past participle, các từ ever, yet, already, for, since và đối chiếu với quá khứ đơn. Bài tập có dạng ''Have you ever...?'', ''I haven''t ... yet'', ''since 2001'' và ''for three years''.\n\nQuy tắc cần nhớ:\n• Cấu trúc luyện trong Unit 9: have/has + past participle.\n• ever/never thường dùng khi nói trải nghiệm; already/yet dùng với việc đã/chưa hoàn thành trong các bài tập.\n• for + khoảng thời gian; since + mốc thời gian.\n• Quá khứ đơn dùng khi thời điểm quá khứ xác định được nêu rõ.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"Have you ever visited London?","explanation":"Ví dụ đúng: Have you ever visited London?","hint":"Cấu trúc luyện trong Unit 9: have/has + past participle.","difficulty":1,"points":10,"options":[{"id":"a","text":"Have you ever visited London?","is_correct":true},{"id":"b","text":"Did you ever visited London?","is_correct":false}]},{"id":"lesson-zero-u21-01-q2","type":"true_false","phase":"language_focus","question":"Unit 9 dùng since với một mốc thời gian.","correct_answer":"True","explanation":"Dựa trên nội dung của Bài tập Tiếng Anh 6 – Unit 9 Cities of the World.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u21-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền have/has: She ___ not seen Nathan since he left.","correct_answer":"has","explanation":"Đáp án: has","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u21-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi chưa ăn trưa.","correct_answer":"I haven''t had lunch yet.","explanation":"Một cách viết theo bài học: I haven''t had lunch yet.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u21-01';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 9 Cities of the World","intro":{"title":"Present Perfect","summary":"Unit 9 luyện hiện tại hoàn thành với have/has + past participle, các từ ever, yet, already, for, since và đối chiếu với quá khứ đơn. Bài tập có dạng ''Have you ever...?'', ''I haven''t ... yet'', ''since 2001'' và ''for three years''.","rules":["Cấu trúc luyện trong Unit 9: have/has + past participle.","ever/never thường dùng khi nói trải nghiệm; already/yet dùng với việc đã/chưa hoàn thành trong các bài tập.","for + khoảng thời gian; since + mốc thời gian.","Quá khứ đơn dùng khi thời điểm quá khứ xác định được nêu rõ."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u21-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"I have already finished my homework.","explanation":"Đáp án phù hợp với quy tắc trong Bài tập Tiếng Anh 6 – Unit 9 Cities of the World.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I have already finished my homework.","is_correct":true},{"id":"b","text":"I already finish my homework yesterday.","is_correct":false},{"id":"c","text":"I has finished my homework.","is_correct":false}]},{"id":"lesson-zero-u21-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền have/has: She ___ not seen Nathan since he left.","correct_answer":"has","explanation":"Đáp án: has","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u21-02-q3","type":"true_false","phase":"language_focus","question":"Unit 9 dùng since với một mốc thời gian.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u21-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Tôi chưa ăn trưa.","correct_answer":"I haven''t had lunch yet.","explanation":"Đáp án mẫu: I haven''t had lunch yet.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u21-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Present Perfect.","correct_answer":"Have you ever visited London?","explanation":"Câu đúng: Have you ever visited London?","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"Have you ever visited London?","is_correct":true},{"id":"b","text":"Did you ever visited London?","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u21-02';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 9 Cities of the World","intro":{"title":"Present Perfect","summary":"Unit 9 luyện hiện tại hoàn thành với have/has + past participle, các từ ever, yet, already, for, since và đối chiếu với quá khứ đơn. Bài tập có dạng ''Have you ever...?'', ''I haven''t ... yet'', ''since 2001'' và ''for three years''.","rules":["Cấu trúc luyện trong Unit 9: have/has + past participle.","ever/never thường dùng khi nói trải nghiệm; already/yet dùng với việc đã/chưa hoàn thành trong các bài tập.","for + khoảng thời gian; since + mốc thời gian.","Quá khứ đơn dùng khi thời điểm quá khứ xác định được nêu rõ."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u21-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Bố bạn đã từng đến London chưa?","correct_answer":"Has your father ever been to London?","explanation":"Đáp án mẫu: Has your father ever been to London?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u21-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền for/since: They have worked here ___ 2001.","correct_answer":"since","explanation":"Đáp án: since","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u21-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Câu nào phù hợp với mốc quá khứ xác định ''in 2010''?","correct_answer":"My family moved to Canada in 2010.","explanation":"Đáp án: My family moved to Canada in 2010.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"My family moved to Canada in 2010.","is_correct":true},{"id":"b","text":"My family has moved to Canada in 2010.","is_correct":false},{"id":"c","text":"My family move to Canada in 2010.","is_correct":false}]},{"id":"lesson-zero-u21-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Present Perfect.","correct_answer":"Have you ever visited London?","explanation":"Ví dụ đúng: Have you ever visited London?","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Have you ever visited London?","is_correct":true},{"id":"b","text":"Did you ever visited London?","is_correct":false}]},{"id":"lesson-zero-u21-03-q5","type":"true_false","phase":"language_focus","question":"Unit 9 dùng since với một mốc thời gian.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Bài tập Tiếng Anh 6 – Unit 9 Cities of the World.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u21-03';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 11 Our Greener World","intro":{"title":"First Conditional","summary":"Unit 11 luyện câu điều kiện loại 1 theo mẫu If + hiện tại đơn, will + động từ để nói về kết quả có thể xảy ra trong tương lai nếu điều kiện được đáp ứng.","rules":["If + present simple, will + V.","Mệnh đề if nêu điều kiện; mệnh đề will nêu kết quả tương lai.","Bài tập của Unit 11 dùng chủ đề môi trường: tái sử dụng, tiết kiệm nước, cây xanh, ô nhiễm."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u22-01-q1","type":"multiple_choice","phase":"pre_task","question":"Unit 11 luyện câu điều kiện loại 1 theo mẫu If + hiện tại đơn, will + động từ để nói về kết quả có thể xảy ra trong tương lai nếu điều kiện được đáp ứng.\n\nQuy tắc cần nhớ:\n• If + present simple, will + V.\n• Mệnh đề if nêu điều kiện; mệnh đề will nêu kết quả tương lai.\n• Bài tập của Unit 11 dùng chủ đề môi trường: tái sử dụng, tiết kiệm nước, cây xanh, ô nhiễm.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"If we use reusable bags, we will reduce waste.","explanation":"Ví dụ đúng: If we use reusable bags, we will reduce waste.","hint":"If + present simple, will + V.","difficulty":1,"points":10,"options":[{"id":"a","text":"If we use reusable bags, we will reduce waste.","is_correct":true},{"id":"b","text":"If we will use reusable bags, we reduce waste.","is_correct":false}]},{"id":"lesson-zero-u22-01-q2","type":"true_false","phase":"language_focus","question":"Trong mẫu Unit 11, mệnh đề if dùng hiện tại đơn.","correct_answer":"True","explanation":"Dựa trên nội dung của Bài tập Tiếng Anh 6 – Unit 11 Our Greener World.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u22-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: If we ___ (not stop) cutting trees, we will endanger our oxygen supply.","correct_answer":"don''t stop","explanation":"Đáp án: don''t stop","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u22-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Nếu bạn học chăm chỉ, bạn sẽ vượt qua kỳ thi.","correct_answer":"If you study hard, you will pass the exam.","explanation":"Một cách viết theo bài học: If you study hard, you will pass the exam.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u22-01';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 11 Our Greener World","intro":{"title":"First Conditional","summary":"Unit 11 luyện câu điều kiện loại 1 theo mẫu If + hiện tại đơn, will + động từ để nói về kết quả có thể xảy ra trong tương lai nếu điều kiện được đáp ứng.","rules":["If + present simple, will + V.","Mệnh đề if nêu điều kiện; mệnh đề will nêu kết quả tương lai.","Bài tập của Unit 11 dùng chủ đề môi trường: tái sử dụng, tiết kiệm nước, cây xanh, ô nhiễm."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u22-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng.","correct_answer":"If it snows tomorrow, I will go skiing.","explanation":"Đáp án phù hợp với quy tắc trong Bài tập Tiếng Anh 6 – Unit 11 Our Greener World.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"If it snows tomorrow, I will go skiing.","is_correct":true},{"id":"b","text":"If it will snow tomorrow, I go skiing.","is_correct":false},{"id":"c","text":"If it snow tomorrow, I will skiing.","is_correct":false}]},{"id":"lesson-zero-u22-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền dạng đúng: If we ___ (not stop) cutting trees, we will endanger our oxygen supply.","correct_answer":"don''t stop","explanation":"Đáp án: don''t stop","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u22-02-q3","type":"true_false","phase":"language_focus","question":"Trong mẫu Unit 11, mệnh đề if dùng hiện tại đơn.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u22-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Nếu bạn học chăm chỉ, bạn sẽ vượt qua kỳ thi.","correct_answer":"If you study hard, you will pass the exam.","explanation":"Đáp án mẫu: If you study hard, you will pass the exam.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u22-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm First Conditional.","correct_answer":"If we use reusable bags, we will reduce waste.","explanation":"Câu đúng: If we use reusable bags, we will reduce waste.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"If we use reusable bags, we will reduce waste.","is_correct":true},{"id":"b","text":"If we will use reusable bags, we reduce waste.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u22-02';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 11 Our Greener World","intro":{"title":"First Conditional","summary":"Unit 11 luyện câu điều kiện loại 1 theo mẫu If + hiện tại đơn, will + động từ để nói về kết quả có thể xảy ra trong tương lai nếu điều kiện được đáp ứng.","rules":["If + present simple, will + V.","Mệnh đề if nêu điều kiện; mệnh đề will nêu kết quả tương lai.","Bài tập của Unit 11 dùng chủ đề môi trường: tái sử dụng, tiết kiệm nước, cây xanh, ô nhiễm."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u22-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Nhiều cá sẽ chết nếu nước bị ô nhiễm.","correct_answer":"A lot of fish will die if the water is polluted.","explanation":"Đáp án mẫu: A lot of fish will die if the water is polluted.","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u22-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: If Henry ___ his exam, his parents will be sad.","correct_answer":"fails","explanation":"Đáp án: fails","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u22-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn vế kết quả phù hợp: If we save water, ...","correct_answer":"we will help the environment.","explanation":"Đáp án: we will help the environment.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"we will help the environment.","is_correct":true},{"id":"b","text":"we helped yesterday.","is_correct":false},{"id":"c","text":"we are save.","is_correct":false}]},{"id":"lesson-zero-u22-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về First Conditional.","correct_answer":"If we use reusable bags, we will reduce waste.","explanation":"Ví dụ đúng: If we use reusable bags, we will reduce waste.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"If we use reusable bags, we will reduce waste.","is_correct":true},{"id":"b","text":"If we will use reusable bags, we reduce waste.","is_correct":false}]},{"id":"lesson-zero-u22-03-q5","type":"true_false","phase":"language_focus","question":"Trong mẫu Unit 11, mệnh đề if dùng hiện tại đơn.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Bài tập Tiếng Anh 6 – Unit 11 Our Greener World.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u22-03';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 12 Robots","intro":{"title":"Could / Will Be Able To","summary":"Unit 12 luyện can cho khả năng hiện tại, could/couldn''t cho khả năng quá khứ và will be able to/won''t be able to cho khả năng tương lai, trong bối cảnh robot và kỹ năng.","rules":["can/can''t: khả năng hiện tại.","could/couldn''t: khả năng trong quá khứ.","will be able to / won''t be able to: khả năng trong tương lai.","Câu hỏi: Could you...?; Will ... be able to...? theo các bài tập của Unit 12."]},"lesson_stage":"learn","exercises":[{"id":"lesson-zero-u23-01-q1","type":"multiple_choice","phase":"pre_task","question":"Unit 12 luyện can cho khả năng hiện tại, could/couldn''t cho khả năng quá khứ và will be able to/won''t be able to cho khả năng tương lai, trong bối cảnh robot và kỹ năng.\n\nQuy tắc cần nhớ:\n• can/can''t: khả năng hiện tại.\n• could/couldn''t: khả năng trong quá khứ.\n• will be able to / won''t be able to: khả năng trong tương lai.\n• Câu hỏi: Could you...?; Will ... be able to...? theo các bài tập của Unit 12.\n\nChọn ví dụ đúng theo phần vừa học.","correct_answer":"I could play chess when I was six.","explanation":"Ví dụ đúng: I could play chess when I was six.","hint":"can/can''t: khả năng hiện tại.","difficulty":1,"points":10,"options":[{"id":"a","text":"I could play chess when I was six.","is_correct":true},{"id":"b","text":"I could played chess when I was six.","is_correct":false}]},{"id":"lesson-zero-u23-01-q2","type":"true_false","phase":"language_focus","question":"Sau could, bài tập dùng động từ nguyên thể.","correct_answer":"True","explanation":"Dựa trên nội dung của Bài tập Tiếng Anh 6 – Unit 12 Robots.","hint":"Đọc lại quy tắc ở đầu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u23-01-q3","type":"fill_blank","phase":"task_cycle","question":"Điền could/couldn''t: We ___ play football because it was raining.","correct_answer":"couldn''t","explanation":"Đáp án: couldn''t","hint":"Áp dụng đúng cấu trúc vừa học.","difficulty":1,"points":10},{"id":"lesson-zero-u23-01-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Trong tương lai, robot sẽ có thể làm việc nhà.","correct_answer":"In the future, robots will be able to do the housework.","explanation":"Một cách viết theo bài học: In the future, robots will be able to do the housework.","hint":"Dùng đúng cấu trúc của chủ điểm.","difficulty":1,"points":10}]}', total_exercises=4, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u23-01';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 12 Robots","intro":{"title":"Could / Will Be Able To","summary":"Unit 12 luyện can cho khả năng hiện tại, could/couldn''t cho khả năng quá khứ và will be able to/won''t be able to cho khả năng tương lai, trong bối cảnh robot và kỹ năng.","rules":["can/can''t: khả năng hiện tại.","could/couldn''t: khả năng trong quá khứ.","will be able to / won''t be able to: khả năng trong tương lai.","Câu hỏi: Could you...?; Will ... be able to...? theo các bài tập của Unit 12."]},"lesson_stage":"practice","exercises":[{"id":"lesson-zero-u23-02-q1","type":"multiple_choice","phase":"pre_task","question":"Chọn câu đúng về khả năng tương lai.","correct_answer":"She will be able to speak English.","explanation":"Đáp án phù hợp với quy tắc trong Bài tập Tiếng Anh 6 – Unit 12 Robots.","hint":"Loại các phương án sai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"She will be able to speak English.","is_correct":true},{"id":"b","text":"She will can speak English.","is_correct":false},{"id":"c","text":"She able to speak English.","is_correct":false}]},{"id":"lesson-zero-u23-02-q2","type":"fill_blank","phase":"task_cycle","question":"Điền could/couldn''t: We ___ play football because it was raining.","correct_answer":"couldn''t","explanation":"Đáp án: couldn''t","hint":"Nhìn chủ ngữ/từ khóa trước khi điền.","difficulty":1,"points":10},{"id":"lesson-zero-u23-02-q3","type":"true_false","phase":"language_focus","question":"Sau could, bài tập dùng động từ nguyên thể.","correct_answer":"True","explanation":"Mệnh đề này được đối chiếu với quy tắc của bài.","hint":"Nhớ quy tắc chính.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]},{"id":"lesson-zero-u23-02-q4","type":"translate","phase":"task_cycle","question":"Dịch sang tiếng Anh: Trong tương lai, robot sẽ có thể làm việc nhà.","correct_answer":"In the future, robots will be able to do the housework.","explanation":"Đáp án mẫu: In the future, robots will be able to do the housework.","hint":"Viết câu ngắn, đúng cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u23-02-q5","type":"multiple_choice","phase":"language_focus","question":"Chọn câu/cụm đúng nhất theo chủ điểm Could / Will Be Able To.","correct_answer":"I could play chess when I was six.","explanation":"Câu đúng: I could play chess when I was six.","hint":"So sánh trực tiếp hai cấu trúc.","difficulty":1,"points":10,"options":[{"id":"a","text":"I could play chess when I was six.","is_correct":true},{"id":"b","text":"I could played chess when I was six.","is_correct":false}]}]}', total_exercises=5, estimated_minutes=25, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u23-02';
UPDATE lessons SET content='{"source_basis":"Bài tập Tiếng Anh 6 – Unit 12 Robots","intro":{"title":"Could / Will Be Able To","summary":"Unit 12 luyện can cho khả năng hiện tại, could/couldn''t cho khả năng quá khứ và will be able to/won''t be able to cho khả năng tương lai, trong bối cảnh robot và kỹ năng.","rules":["can/can''t: khả năng hiện tại.","could/couldn''t: khả năng trong quá khứ.","will be able to / won''t be able to: khả năng trong tương lai.","Câu hỏi: Could you...?; Will ... be able to...? theo các bài tập của Unit 12."]},"lesson_stage":"apply-test","exercises":[{"id":"lesson-zero-u23-03-q1","type":"translate","phase":"pre_task","question":"Dịch sang tiếng Anh: Bạn có thể nói tiếng Anh khi bạn năm tuổi không?","correct_answer":"Could you speak English when you were five?","explanation":"Đáp án mẫu: Could you speak English when you were five?","hint":"Tự viết trước khi xem gợi ý.","difficulty":1,"points":10},{"id":"lesson-zero-u23-03-q2","type":"fill_blank","phase":"task_cycle","question":"Điền: Some robots ___ recognise faces now. (can/could)","correct_answer":"can","explanation":"Đáp án: can","hint":"Kiểm tra từ khóa và cấu trúc.","difficulty":1,"points":10},{"id":"lesson-zero-u23-03-q3","type":"multiple_choice","phase":"task_cycle","question":"Chọn câu nói về khả năng quá khứ.","correct_answer":"Dave could play tennis well when he was young.","explanation":"Đáp án: Dave could play tennis well when he was young.","hint":"Chọn phương án tuân theo quy tắc của bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"Dave could play tennis well when he was young.","is_correct":true},{"id":"b","text":"Dave can play tennis when he was young.","is_correct":false},{"id":"c","text":"Dave will be able to play yesterday.","is_correct":false}]},{"id":"lesson-zero-u23-03-q4","type":"multiple_choice","phase":"language_focus","question":"Ôn nhanh: chọn ví dụ đúng về Could / Will Be Able To.","correct_answer":"I could play chess when I was six.","explanation":"Ví dụ đúng: I could play chess when I was six.","hint":"Nhớ lại phần Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"I could play chess when I was six.","is_correct":true},{"id":"b","text":"I could played chess when I was six.","is_correct":false}]},{"id":"lesson-zero-u23-03-q5","type":"true_false","phase":"language_focus","question":"Sau could, bài tập dùng động từ nguyên thể.","correct_answer":"True","explanation":"Đối chiếu với nội dung nguồn: Bài tập Tiếng Anh 6 – Unit 12 Robots.","hint":"Nếu chưa chắc, quay lại bài Hiểu bài.","difficulty":1,"points":10,"options":[{"id":"a","text":"True","is_correct":true},{"id":"b","text":"False","is_correct":false}]}]}', total_exercises=5, estimated_minutes=20, updated_at='2026-10-01T00:00:00.000Z' WHERE id='lesson-zero-u23-03';

UPDATE courses SET total_lessons=69, total_xp=(SELECT COALESCE(SUM(l.xp_reward),0) FROM lessons l JOIN units u ON l.unit_id=u.id WHERE u.course_id='course-en-zero-69'), estimated_duration=(SELECT COALESCE(SUM(l.estimated_minutes),0) FROM lessons l JOIN units u ON l.unit_id=u.id WHERE u.course_id='course-en-zero-69'), updated_at='2026-10-01T00:00:00.000Z' WHERE id='course-en-zero-69';
